(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-smoothquant-accurate-and-efficient-p-2022"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-1\">一 · 一个被离群通道拖垮的在线服务</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-2\">二 · 旧方案的两条死路：精度与内核效率不可兼得</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-3\">三 · 为什么不能靠“更细的校准”绕过去</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-4\">四 · 旧方案在显存与带宽账本上的具体亏空</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-5\">五 · 旧方案留下的三个工程债</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-6\">六 · 失败模式的现场形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-7\">七 · 从请求形状反推量化粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-8\">八 · 并发与批大小如何挤压校准的有效性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-9\">九 · SLO 与长尾：量化收益被谁吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-10\">十 · 分离式部署下按阶段校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-11\">十一 · 负载反向限制方案：alpha 与粒度的部署旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-12\">十二 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-13\">十三 · 从缩放因子到内核布局：SmoothQuant 在 Blackwell 上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-14\">十四 · 数据类型阶梯：FP16/BF16、FP8、NVFP4 与累加精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-15\">十五 · Blackwell 特性如何改变量化内核的写法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-16\">十六 · 误差预算：平滑强度、量化粒度与累加三者的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-17\">十七 · 音频生成场景的算子映射与校准差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-18\">十八 · 内核实现判断：格式、粒度、累加三者的取舍顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-19\">十九 · 显存账本的三个账户与比特数的线性效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-20\">二十 · 分页：把连续假设换成块表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-21\">二十一 · 压缩与复用：KV 的比特与结构两条路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-22\">二十二 · 带宽瓶颈的定位：算术强度与每 token 字节数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-23\">二十三 · 可复算的显存预算模板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-24\">二十四 · 校准漂移与账本的动态性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-25\">二十五 · 平滑之后，显存账本与 KV 边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-26\">二十六 · 连续批处理：把 KV cache 的碎片时间收回来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-27\">二十七 · Chunked prefill：把长 prompt 切成不阻塞解码的片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-28\">二十八 · 优先级与抢占：尾延迟是被谁拖长的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-29\">二十九 · 分离式预填/解码：把两种负载放到不同资源池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-30\">三十 · 时延与吞吐的取舍：用预算而不是平均值来定容量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-31\">三十一 · 量化参数在调度面上的耦合：连续批处理、chunked prefill 与分离式部署的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-32\">三十二 · 切分维度与通信原语的对应关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-33\">三十三 · NVLink 5 与 NVSwitch：把 All-Reduce 压进计算阴影里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-34\">三十四 · All-to-All 与 EP：路由倾斜才是真瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-35\">三十五 · NIXL 传输与分离式部署的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-36\">三十六 · 通信何时成为瓶颈：三个可操作的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-37\">三十七 · 量化参数在并行切分与通信拓扑上的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-38\">三十八 · 精度塌陷的三种可辨识形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-39\">三十九 · OOM 与显存账本的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-40\">四十 · 批抖动与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-41\">四十一 · 静默降级：没有报错的精度流失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-42\">四十二 · 定位与回滚的工程路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-43\">四十三 · 失效链与灰度回退：从极值漂移到静默降级的定位手法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-44\">四十四 · 基准口径的三层结构：模型、硬件档位、负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-45\">四十五 · 指标语义：TTFT、TPOT、吞吐、显存、功耗各自度量什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-46\">四十六 · batch 与并发：为什么“同一加速比”在不同负载下不成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-47\">四十七 · 校准口径：分布、序列长度与阶段差异如何污染数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-48\">四十八 · 哪些提升不可比：五类常见误读</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-49\">四十九 · 监控项与失败模式如何进入基准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-50\">五十 · 迁移到新模型：先判断“离群通道是否仍是主要矛盾”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-51\">五十一 · 迁移到新领域：校准分布决定成败，音频是最典型的反例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-52\">五十二 · 迁移到分离式部署：预填与解码必须分阶段校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-53\">五十三 · 规模上限：比特数、粒度与内核布局三者互相牵制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-54\">五十四 · 不适用清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-55\">五十五 · 迁移边界：平滑系数不是常数，量化粒度决定收益能否落地</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:590px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 590.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">校准集前向采集各线性层输入激活的逐通道最大绝对值与权重逐通道最大绝对值。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按通道计算平滑系数，将激活离群通道的尺度部分转移至权重对应列，得到等价…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对变换后权重做逐通道量化，对变换后激活做逐张量或按 token 分组量…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时激活先乘平滑系数再做低精度量化，与低精度权重在整数或低精度张量核…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">累加结果按输出通道缩放因子反量化回高精度，进入下一层或写出 KV ca…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"508.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对注意力与全连接层统一套用同一变换流程，形成整网 W8A8 推理图。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-1\">一 · 一个被离群通道拖垮的在线服务</h3>\n<p>设想一个部署在 GB200 NVL72 机架上的多租户推理服务：白天承载客服对话与代码补全，夜间承接批量文档摘要。运维侧的诉求很朴素——把权重和激活都压到 8 比特，让每张 B200 的 HBM 能多装几份模型、让矩阵乘少读一半字节。工程团队按常规路径做了权重逐通道 INT8 量化，激活则沿用逐张量 INT8：一个张量一个缩放因子，内核实现最简，矩阵乘可以直接走整数张量核，累加布局与访存模式都不需要改动。上线前的离线评测看起来尚可，上线后长尾请求开始出问题：部分层的激活出现极值远超其余通道的离群通道，逐张量缩放因子被这几个通道独占，剩余通道的有效量化级被压到个位数，输出出现重复片段与截断。这就是 SmoothQuant 面对的问题现场：不是量化本身不可行，而是量化粒度与激活分布的形状不匹配。</p>\n<p>要理解痛点，先把逐张量量化的误差写清楚。设某线性层输入激活为 <span>X</span>，逐张量对称量化的缩放因子为 <span>s<sub>X</sub> = max(|X|)/127</span>，则任一元素的重建误差上界约为 <span>s<sub>X</sub>/2</span>。当某一通道的极值比其余通道大一个数量级以上时，<span>s<sub>X</sub></span> 由该通道决定，其余通道的量化步长被同比放大，信噪比按步长平方倒数下降。换句话说，少数通道的数值范围绑架了整个张量的量化预算，这是逐张量激活量化在 LLM 上精度崩塌的直接机制。</p>\n<div class=\"formula\">$$ \\mathrm{SNR}_j \\approx 20\\log_{10}\\frac{\\max(|X_{:,j}|)}{\\max(|X|)/127} $$</div>\n<p>上式说明：通道 <span>j</span> 的有效比特数取决于它自己的极值与全局极值之比。离群通道占比越小、幅度越大，其余通道损失越重。工程上的代价是可量化的：激活精度不足会直接传导到注意力输出与 KV cache 写入，长上下文下误差沿 token 维累积；而为了保住精度回退到 FP16 激活，则矩阵乘的带宽需求翻倍，在 decode 阶段这个代价尤其昂贵——decode 是访存受限的，权重与激活的字节数几乎线性决定每 token 延迟。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-2\">二 · 旧方案的两条死路：精度与内核效率不可兼得</h3>\n<p>论文之前，推理栈面对离群通道基本只有两条路，且都不通。第一条是提高激活量化粒度：从逐张量退到逐通道，每个输入通道一个缩放因子。这在数值上确实能救回精度，因为离群通道用自己的缩放因子吸收了自己的动态范围。但逐通道激活量化与 GPU 矩阵乘内核的粒度不匹配：矩阵乘沿 K 维累加，内核期望激活侧以一个统一的缩放因子参与整块累加，逐通道缩放意味着每个 K 元素都要带一个不同的尺度，要么在加载时做额外重排与逐元素乘，要么在累加后无法用一次反量化收尾。访存开销与指令开销上升，抵消了低精度带来的带宽收益，高吞吐内核退化为带宽受限的逐元素路径。</p>\n<p>第二条路是混合精度：把离群通道挑出来留在 FP16，其余通道走 INT8。这避免了逐通道缩放的内核问题，但引入了新的结构性代价。离群通道的位置随模型层、随输入分布漂移，内核需要按掩码做分支或分段，矩阵乘被切成不规则形状，张量核利用率下降；更麻烦的是，分离出的高精度通道在张量并行切分后落在不同卡上，通信量与同步点增加。对于分离式预填/解码部署，预填阶段与解码阶段的激活极值分布不同，同一套掩码无法复用，量化参数需按阶段分别校准，运维复杂度陡增。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>精度</th><th>内核效率</th><th>主要代价</th></tr></thead><tbody><tr><td>W8A16（仅权重量化）</td><td>高</td><td>高</td><td>激活仍占 16 比特，decode 带宽减半但未到位</td></tr><tr><td>W8A8 逐张量激活</td><td>离群通道下崩塌</td><td>最高</td><td>有效比特骤降，长尾请求输出劣化</td></tr><tr><td>W8A8 逐通道激活</td><td>可恢复</td><td>低</td><td>重排与逐元素缩放，访存开销上升</td></tr><tr><td>混合精度挑通道</td><td>较高</td><td>中</td><td>不规则切分、跨卡同步、按阶段重校准</td></tr></tbody></table>\n<p>这张表的关键判断是：精度与内核效率在旧方案里是互斥的。要么牺牲精度换吞吐，要么牺牲吞吐换精度，没有第三条路。而在线服务的 SLO 恰恰同时压这两头——首包延迟要求 decode 阶段带宽尽可能低，输出质量要求激活量化不能崩。这就是非改不可的原因：不是学术上的精度指标，而是服务侧同时被延迟与质量夹击。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-3\">三 · 为什么不能靠“更细的校准”绕过去</h3>\n<p>一个自然的反应是：既然问题出在极值估计，那就把校准做得更细——更多样本、更长序列、更广领域覆盖。这条路能缓解但不能根治，因为离群通道是激活分布的固有形状，不是估计噪声。校准只能让缩放因子更准确地反映真实极值，而真实极值本身就意味着逐张量量化的预算被少数通道占用。校准越准，反而越确认了“这个张量不适合逐张量量化”这一事实。</p>\n<p>更细的校准还有部署侧代价。校准是前向统计，需要覆盖目标部署的上下文分布；长上下文请求会放大激活极值波动，校准集必须包含长序列样本，否则缩放系数失准。对多租户服务，不同业务的输入分布差异大，一套校准参数难以覆盖全部流量；按业务分别校准意味着多套量化参数与多份权重副本，显存占用随副本数线性上升，这与量化的初衷背道而驰。校准样本规模与领域覆盖决定极值估计稳定性，进而影响离群通道识别——这是一个一次性离线开销，但它把“分布偏移”的风险固化进了部署参数里：一旦线上流量漂移，某层激活超出量化范围，表现为输出重复或截断，工程上只能按层回退高精度并监控逐层极值漂移。</p>\n<p>所以问题的本质不是“校准不够好”，而是“逐张量量化的粒度与激活分布的形状不匹配”。要解决它，必须改变量化难度的分布本身，而不是更努力地去估计一个注定被离群通道主导的缩放因子。这正是 SmoothQuant 的切入点：用数学等价的通道级变换，把激活的量化难度迁移一部分到权重上，让激活在逐张量粒度下也可量化，同时保持内核友好。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-4\">四 · 旧方案在显存与带宽账本上的具体亏空</h3>\n<p>把代价算成账本更清楚。以 decode 阶段为例，每生成一个 token，需要读取全部权重与 KV cache。权重从 FP16 压到 INT8，字节数减半，这是 W8A16 已经拿到的收益；但激活若仍是 FP16，注意力投影与 FFN 的输入激活读写仍按 16 比特计，矩阵乘的带宽需求只减了权重那一半。若激活也能压到 INT8，矩阵乘两侧的字节数同时减半，decode 的每 token 延迟才有机会接近减半——前提是内核能在整数或低精度张量核上完成累加，且反量化不引入额外访存。</p>\n<div class=\"formula\">$$ T_{\\text{decode}} \\approx \\frac{B_W + B_A + B_{KV}}{\\text{HBM 带宽}} $$</div>\n<p>这个简化式子里，<span>B<sub>A</sub></span> 是激活字节数，<span>B<sub>KV</sub></span> 是 KV cache 字节数。逐通道激活量化会让 <span>B<sub>A</sub></span> 的有效读取变大——每个 K 元素附带一个缩放因子，或者需要一次重排把激活整理成内核期望的布局，实际访存超过名义比特数。混合精度挑通道则让矩阵乘切成不规则块，张量核利用率下降，等效吞吐损失比字节数节省更显著。这两条路都把账本上的收益吃掉了。</p>\n<p>具体到一个可核验的机制性例子：某层输入通道的激活极值远大于其余通道，若直接逐张量量化，该通道决定缩放因子，其余通道仅剩极少有效量化级。工程团队此时面对的选择是——接受精度损失上线，或者回退 FP16 激活让 decode 带宽账本回到原点。SmoothQuant 的处理是：计算该通道平滑系数大于一，把激活该通道除以系数使其落入正常动态范围，同时把权重对应列乘以同系数，权重列极值随之变大但仍可由逐通道量化吸收。推理时激活先做除法再量化，权重已离线量化，矩阵乘在低精度下完成，输出与原始高精度层在数值上近似等价。账本上，激活与权重同时按 8 比特计，且量化粒度保持逐张量或按 token 分组，内核无需重排。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-5\">五 · 旧方案留下的三个工程债</h3>\n<p>第一笔债是内核布局与量化粒度的错配。逐通道激活量化在数值上正确，但它要求内核在 K 维上携带逐元素尺度，这与高吞吐矩阵乘内核的累加布局冲突。工程上要么写一个专门的低效内核，要么在加载阶段做重排，两者都让访存开销上升。这笔债在预填阶段尚可容忍（预填是计算受限的，算力有余量），在 decode 阶段则是致命的（decode 是访存受限的，任何额外访存都直接加延迟）。</p>\n<p>第二笔债是量化参数与并行拓扑的耦合。张量并行把权重按输出通道或输入通道切分，逐通道激活量化的缩放因子需要按切分后的局部通道重新统计，否则跨卡不一致会导致累加结果偏差。这意味着量化参数的校准必须感知并行切分方式，换一种切分就要重新校准，部署灵活性下降。逐张量激活量化没有这个问题，因为缩放因子是全局的，切分后仍然一致——这也是旧方案里逐张量粒度被广泛采用的原因，它的内核友好性来自参数与切分的解耦。</p>\n<p>第三笔债是 KV cache 与激活量化的误差叠加。KV cache 通常保持高精度或单独量化，若与权重激活量化共用缩放因子，误差会在注意力计算中叠加。旧方案在激活精度不足时，往往被迫把 KV cache 也留在高精度以稳住长上下文质量，这进一步压缩了显存收益。SmoothQuant 的通道平滑不直接解决 KV cache 量化，但它让激活在 W8A8 下可用，从而把“激活精度”这一项从误差预算里移除，留给 KV cache 的策略空间更大。</p>\n<p>这三笔债共同指向一个判断：旧方案的问题不在某一个环节，而在量化粒度、内核布局、并行切分、KV cache 策略四者之间的耦合。任何只改其中一项的方案都会被其他三项拉回去。SmoothQuant 的价值在于它只改量化难度的分布，不动模型结构、不动并行拓扑、不动内核布局，因此不触发这些耦合项——这是它作为部署侧基础算子的工程意义，也是这篇论文之前推理栈非改不可的根本原因。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-6\">六 · 失败模式的现场形态</h3>\n<p>把失败模式写成现场形态，比抽象描述更有用。校准分布偏移导致某层激活溢出量化范围时，输出表现为重复片段或截断——重复是因为注意力分布被量化误差扭曲后模型退化为低熵复制，截断是因为超出范围的激活被钳位后前馈层输出饱和。工程上的处置是按层回退高精度并监控逐层极值漂移，但回退意味着该层权重与激活重新占用 16 比特，显存账本出现一个洞，且这个洞的位置随流量漂移而移动。</p>\n<p>另一个现场形态是把平滑强度当作固定常数套用到所有层。平滑强度参数在激活与权重之间分配量化难度：取值偏向激活侧则激活更易量化、权重量化误差上升；偏向权重侧则相反。固定常数会让部分层权重量化误差上升，表现为该层输出与高精度输出的余弦相似度下降，端到端则体现为生成质量在特定输入类型上劣化。正确做法是按层类型分别调优，注意力投影层与前馈层的激活分布形状不同，最优平滑强度也不同。这笔调优开销是部署侧的一次性成本，但它把“量化参数”从全局常数变成了逐层配置，运维上需要版本化管理。</p>\n<p>还有一个容易被忽略的形态：只关注权重量化而忽略激活量化粒度与内核布局的匹配。团队把权重压到 INT8 拿到显存收益，激活仍走逐通道量化，推理时引入额外重排开销，端到端延迟不降反升。这类失败在压测中不易发现，因为离线吞吐测试的批大小与线上不同，重排开销在 decode 的小批场景下占比更高。判断标准很直接：看 decode 阶段每 token 延迟是否随比特数下降而同比下降，若没有，说明量化粒度与内核布局没有对齐，显存收益被访存开销抵消。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-7\">七 · 从请求形状反推量化粒度</h3>\n<p>在 Blackwell 上谈 W8A8，绕不开一个前提：量化粒度不是数学选择，而是负载选择。SmoothQuant 把激活的离群通道难度迁移到权重，最终仍要落到一个内核能吃的粒度上——逐张量、或按 token 分组。这个粒度直接决定请求形态如何映射到硬件。以 B200 的 tcgen05 MMA 为例，矩阵乘的累加布局要求操作数在 K 维上连续分块，激活若按 token 分组量化，缩放因子随 token 走，内核可在每个 tile 载入时广播一组标量；若强行逐通道量化激活，则需要在 K 维上插入重排与逐元素缩放，TMEM 的载入节奏被打断，访存开销上升，收益被抵消。因此一个部署方案的第一个判断不是“能不能 W8A8”，而是“我的请求里 token 维度是否足够规整，让按 token 分组的缩放因子摊薄到足够多的乘加上”。</p>\n<p>请求长度分布在这里是硬约束。短 prompt、高并发、每请求几十个 token 的场景，按 token 分组的缩放因子数量与 token 数同阶，摊薄效果差，量化元数据的带宽占比上升；反过来，长上下文预填阶段单请求数千 token，分组缩放几乎免费。于是同一套 SmoothQuant 参数在预填与解码两个阶段的表现不同：预填吃满矩阵乘、量化收益直接体现为权重与激活带宽下降；解码阶段每步只处理一个或几个 token，矩阵乘退化为窄向量乘，此时瓶颈从算力转向 KV cache 与权重读取，激活量化的边际收益变小，而权重逐通道量化（缩放因子离线固化进权重布局）仍是主要显存收益来源。</p>\n<div class=\"formula\">$$ \\text{有效吞吐} \\approx \\frac{B \\cdot \\bar{L}_{out}}{\\tau_{pre} + \\bar{L}_{out}\\cdot \\tau_{dec}},\\quad \\tau_{dec} \\propto \\frac{W_{bytes} + KV_{bytes}}{BW} $$</div>\n<p>这个式子说明：解码步时间由权重字节与 KV 字节除以带宽主导，量化把 W_bytes 按比特数线性压低，但 KV cache 若保持高精度则不被这部分收益覆盖。因此负载形态里的输出长度均值与方差，决定了权重收益能否被摊薄到足够多的解码步上。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-8\">八 · 并发与批大小如何挤压校准的有效性</h3>\n<p>SmoothQuant 的平滑系数由激活逐通道最大绝对值与权重逐通道最大绝对值按 alpha 组合，极值估计来自校准前向。这里有一个容易被忽略的耦合：校准时的批大小与部署时的批大小不一致，会改变激活极值的统计。连续批处理把不同请求拼进同一前向，激活张量的 token 维被来自不同分布的请求填充，逐通道极值是这批 token 上的最大值。若校准只用单条短样本，极值偏低；部署时高并发拼批，某个长尾请求的离群通道把该通道极值推高，预先算好的缩放因子就显得过小，激活在量化后溢出，表现为输出重复或截断。工程上可核查的口径是：在校准阶段记录每层激活逐通道极值，并在部署侧以固定采样率回采真实请求的逐层极值，比较两者的分位数漂移；漂移超过阈值即触发该层回退高精度或重校准。</p>\n<p>批大小还反向限制方案。W8A8 让权重与激活显存下降，理论上允许更大批以提升吞吐，但 KV cache 不随权重比特数下降，批大小的实际上限由 KV 显存与 SLO 共同决定。Blackwell 的 HBM 容量提升给了更大余量，但 NVL72 机柜级部署里，跨卡张量并行切分后每卡持有的 KV 分片与量化缩放因子需按切分后的局部通道重新统计——这是并行拓扑对量化方案的直接约束：全局统计的平滑系数在切分后不再对应局部极值，跨卡不一致会让某张卡上的层先溢出。</p>\n<ul>\n<li>可核查口径一：校准批大小与部署拼批分布的 token 长度直方图对齐度。</li>\n<li>可核查口径二：部署侧逐层激活极值的 P99 与校准极值之比，作为溢出预警指标。</li>\n<li>可核查口径三：张量并行切分后各卡局部通道极值的最大差异，作为是否需要分卡重校准的判据。</li>\n</ul>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-9\">九 · SLO 与长尾：量化收益被谁吃掉</h3>\n<p>推理 SLO 通常由首包延迟（TTFT）与每 token 间隔（TPOT）两个分位数刻画，而不是均值。长尾请求——超长 prompt、罕见领域输入——在这两个指标上都是尾部贡献者。SmoothQuant 的收益在均值意义上明确：权重与激活比特数下降，矩阵乘带宽需求下降；但长尾请求的激活分布恰恰是校准集覆盖最差的部分，离群通道更极端，逐张量量化的缩放因子被单个通道主导的程度更深。于是出现一个反直觉的工程判断：量化方案在均值负载上表现良好，却可能在 SLO 的 P99 上恶化，因为尾部请求触发了按层回退高精度的路径，回退本身带来分支与额外内核启动，延迟反而高于未量化的基线。</p>\n<p>这要求把回退机制设计成可预测的。一种做法是把逐层极值监控做成前置检查：请求进入预填前，按其 prompt 长度与领域标签查表决定该请求走量化路径还是高精度路径，而不是在计算中途发现溢出再回退。代价是路径分叉降低了批的规整度，连续批处理需要在同一批内混合两种精度的层，内核调度复杂度上升。可核查的口径是：按请求长度分桶统计 TTFT 与 TPOT 的 P99，并记录回退触发率；若回退集中在某个长度桶，说明校准集在该桶的覆盖不足，应补校准样本而非调 alpha。</p>\n<table class=\"mini\">\n<thead><tr><th>负载特征</th><th>对量化方案的塑造</th><th>系统代价</th></tr></thead>\n<tbody>\n<tr><td>短 prompt、高并发</td><td>按 token 分组缩放摊薄不足，倾向逐张量</td><td>量化元数据带宽占比上升</td></tr>\n<tr><td>长上下文预填</td><td>分组缩放几乎免费，收益最大</td><td>激活极值波动放大，校准需覆盖长序列</td></tr>\n<tr><td>解码主导</td><td>权重逐通道量化为主收益</td><td>KV cache 高精度，显存收益不完全</td></tr>\n<tr><td>长尾领域输入</td><td>极值偏移，触发按层回退</td><td>路径分叉，批规整度下降</td></tr>\n</tbody>\n</table>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-10\">十 · 分离式部署下按阶段校准</h3>\n<p>分离式预填/解码把两个阶段的资源池分开，也让量化参数的统计口径必须分开。预填阶段一次处理整段 prompt，激活张量的 token 维是完整上下文，逐通道极值是整段上的最大值；解码阶段每步只喂入新 token 与 KV cache，激活极值来自单 token 分布，量级通常远低于预填。若两阶段共用一套按预填统计的缩放因子，解码阶段的激活被过度压缩到量化区间的低端，有效比特数骤降，精度在长解码链上累积塌陷。可核查的口径是：分别统计预填与解码阶段各层激活逐通道极值，比较两者的比值分布；比值偏离大的层必须分阶段求平滑系数。</p>\n<p>这一拆分在 NVL72 机柜里还牵动通信。预填池与解码池之间通过 NIXL 搬运 KV cache，若 KV 保持高精度，搬运字节数不受权重量化影响；若对 KV 单独量化，则需在搬运前完成量化、搬运后反量化，NIXL 的传输粒度与量化分组粒度必须对齐，否则搬运变成逐元素操作，NVLink 5 的带宽优势被协议开销吃掉。工程判断是：KV 量化只在解码池内部显存压力成为瓶颈时启用，且分组粒度对齐传输块大小，不与权重激活共用缩放因子以避免误差叠加。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-11\">十一 · 负载反向限制方案：alpha 与粒度的部署旋钮</h3>\n<p>alpha 取零退化为仅权重量化、取一退化为仅激活平滑，这个连续旋钮在负载视角下不是精度调参，而是负载适配。当部署负载以解码为主、KV 显存吃紧时，alpha 偏小、把难度留在权重侧更划算，因为权重逐通道量化的缩放因子离线固化，不占运行时带宽；当负载以长预填为主、矩阵乘吃满时，alpha 偏大、把激活动态范围压下来，让按 token 分组量化在高吞吐内核上跑满。过度平滑会把量化难度推给权重，权重逐通道量化误差上升，这一代价在权重读取主导的解码阶段会被放大，因为每步都要读全部权重。</p>\n<p>粒度选择同样被负载反向约束。逐通道激活量化在数学上更精细，但需要额外重排与缩放，访存开销上升；在 Blackwell 的 tcgen05 路径上，这个开销体现为 TMEM 载入与 MMA 发射之间的气泡。因此除非负载的 token 维足够大、能把重排开销摊薄，否则不应选择逐通道激活量化。可核查的口径是：在同一负载下对比逐张量与按 token 分组两种粒度的端到端 TPOT 与精度余弦相似度，若分组粒度的精度损失在可接受范围内而 TPOT 明显更优，则粒度选择应由负载而非理论精度决定。</p>\n<ul>\n<li>机制：alpha 在激活与权重之间分配量化难度，等价变换不改变层输出，但改变运行时哪一侧承担缩放开销。</li>\n<li>代价：alpha 偏大时权重列极值变大，逐通道量化步长变粗，解码阶段权重读取的精度损失累积。</li>\n<li>例子：音频生成场景输入为声学特征或文本 token，长度短且方差大，需单独校准；用文本校准集直接校准会使声码器前馈层输出明显失真。</li>\n</ul>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-12\">十二 · 可核查的测量口径清单</h3>\n<p>把上述判断落成可复核的测量，需要固定口径而非笼统报吞吐。第一，请求长度分布必须给出直方图与分位数，而不是均值，因为量化收益与极值统计都对尾部敏感。第二，TTFT 与 TPOT 必须按长度桶与领域标签分桶报 P50/P99，并同时报回退触发率，否则量化方案的 SLO 表现无法归因。第三，逐层激活极值漂移需以部署侧回采与校准极值的比值分布呈现，这是判断校准集覆盖是否足够的直接证据。第四，显存口径要区分权重、激活、KV cache 三部分，权重随比特数线性下降，激活随批与序列长度变化，KV 不随权重量化下降，三者混报会掩盖真实瓶颈。第五，带宽口径要区分预填与解码阶段，解码阶段的权重读取带宽是量化收益的主要落点。</p>\n<p>这些口径共同指向一个工程判断：SmoothQuant 在 Blackwell 上的部署价值不取决于把比特数压到多低，而取决于校准分布与部署负载分布的重合度。重合度高时，逐张量或按 token 分组的粗粒度量化足以在硬件友好的内核布局下拿到显存与带宽收益；重合度低时，任何 alpha 调优都只是在均值上好看，长尾请求会以按层回退的形式把延迟还回来。因此校准集的序列长度覆盖必须对齐目标部署的上下文分布，长上下文请求会放大激活极值波动，校准集缺长序列样本就会让缩放系数失准——这是负载塑造方案的最直接一环，也是方案反过来限制可服务负载边界的机制所在。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-13\">十三 · 从缩放因子到内核布局：SmoothQuant 在 Blackwell 上的落点</h3>\n<p>SmoothQuant 的等价变换本身只是逐通道对角缩放，真正决定它在 Blackwell 上跑得快不快的，是变换之后量化粒度与矩阵乘内核布局是否对齐。公式逐项看：</p>\n<div class=\"formula\">$$ \\mathbf{Y} = (\\mathbf{X}\\,\\mathrm{diag}(\\mathbf{s})^{-1})\\cdot(\\mathrm{diag}(\\mathbf{s})\\,\\mathbf{W}) + \\mathbf{b},\\quad s_j = \\frac{\\max(|\\mathbf{X}_{:,j}|)^{\\alpha}}{\\max(|\\mathbf{W}_{j,:}|)^{1-\\alpha}} $$</div>\n<p>第一项 <strong>X·diag(s)⁻¹</strong> 是推理时在激活侧执行的逐输入通道除法，第 j 个输入通道的激活被除以 s_j；第二项 <strong>diag(s)·W</strong> 是离线把权重第 j 行（对应输入通道 j 的列）乘以同一 s_j。两者乘积在实数域严格等于原层输出，因此量化误差只来自后续的低精度表示，不来自变换本身。第三项 b 是偏置，不参与缩放。s_j 的构造里，分子是激活第 j 通道的逐通道最大绝对值，分母是权重第 j 输入通道的最大绝对值，α 在两者之间分配量化难度：α=0 时 s_j≡1，退化为纯权重量化；α=1 时 s_j 完全由激活极值决定，激活被压到单位动态范围而权重列被放大。α 是部署侧唯一需要调的旋钮，且必须按层类型分别取值——注意力投影层与 FFN 的激活/权重极值比例不同，统一常数会让部分层权重量化误差上升。</p>\n<p>工程代价在这里第一次显形：激活侧的除法是逐通道的，若量化粒度是逐通道激活，内核必须在矩阵乘前做重排与逐通道缩放，访存开销上升、无法复用高吞吐张量核路径。SmoothQuant 的取舍是保持激活逐张量或按 token 分组量化，把逐通道自由度全部推给离线权重，于是推理内核看到的仍是一个标量缩放因子加一个低精度矩阵，能直接落进标准 GEMM 流水。举例：某线性层输入通道 4096，其中一个通道激活极值比其他通道高一个数量级，逐张量量化下该通道独占缩放因子，其余通道有效量化级骤降；平滑后该通道 s_j>1，激活被压回正常范围，权重对应列极值变大但由逐通道权重量化吸收，整层在 W8A8 下恢复精度。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-14\">十四 · 数据类型阶梯：FP16/BF16、FP8、NVFP4 与累加精度</h3>\n<p>Blackwell 世代的推理精度不是单点选择，而是一条从 FP16/BF16 到 FP8 再到 NVFP4 的阶梯，每一级都改变 SmoothQuant 变换后的误差结构。FP16 与 BF16 都是 16 比特，但指数位与尾数位分配不同：BF16 指数位宽、动态范围大、尾数少，适合承载激活极值波动大的张量；FP16 尾数多、动态范围窄，在激活极值接近上限时有溢出风险。SmoothQuant 把激活动态范围收窄后，两者都能安全承载，但 BF16 对残余离群通道更宽容。</p>\n<p>FP8 分 E4M3 与 E5M2 两种格式，前者尾数多适合权重与激活，后者动态范围大适合梯度类场景。W8A8 的“8 比特”在 Blackwell 上通常指 FP8 而非 INT8：FP8 的缩放是浮点的，量化步长随指数变化，离群通道被平滑后剩余通道的有效比特数比 INT8 均匀步长更可控。代价是 FP8 矩阵乘的累加仍在更高精度完成，累加器位宽决定长 K 维度下的误差累积速度。公式上，一次 GEMM 的输出误差可写成：</p>\n<div class=\"formula\">$$ \\epsilon \\approx \\sum_{k} \\left( \\delta x_k \\cdot w_k + x_k \\cdot \\delta w_k \\right) + \\epsilon_{\\text{acc}}(K) $$</div>\n<p>前两项是激活与权重量化误差的线性叠加，第三项是累加器在 K 次累加后的舍入误差，随 K 增长。SmoothQuant 通过把激活误差转移到权重（α 调节）改变前两项的相对大小，但无法消除第三项——这正是 Blackwell 张量核把累加精度做高的动机。NVFP4 是更激进的 4 比特浮点块格式，权重与激活按小块共享缩放因子，显存与带宽收益翻倍，但对激活离群通道的容忍度极低，SmoothQuant 的通道平滑在此变成前置必要条件而非可选优化：不平滑直接上 NVFP4，离群通道会撑爆块缩放因子，块内其余元素有效比特数崩塌。</p>\n<p>系统代价按阶梯递减：权重显存随比特数线性下降，矩阵乘的带宽需求同比例下降，而算力利用率取决于张量核是否原生支持该格式。FP8 在 Blackwell 上有原生路径，NVFP4 需要块缩放元数据的额外访存，元数据布局若与内核访存模式不匹配，带宽收益会被元数据读取抵消。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-15\">十五 · Blackwell 特性如何改变量化内核的写法</h3>\n<p>tcgen05 是 Blackwell 第五代 Tensor Core 的指令族，它把矩阵乘的调度从 warp 级上升到 CTA 级甚至 CTA 对级，累加器不再放在寄存器堆而是落在 TMEM（Tensor Memory）中。对量化内核的直接后果是：累加精度与累加器容量解耦，长 K 维度的 GEMM 可以把累加结果留在 TMEM 里跨指令累积，减少寄存器压力与中间写回，累加误差的累积路径更短。SmoothQuant 变换后的权重是逐通道量化的，其缩放因子离线固化进权重布局，tcgen05 内核读取权重时按块加载，缩放因子随块元数据一起进入 TMEM 侧的累加后处理，反量化在累加完成后按输出通道一次性执行，而不是每个 K 块都反量化一次——这减少了反量化指令数，也避免了中间精度损失。</p>\n<p>2-SM MMA 是 Blackwell 上两个 SM 协同执行一次矩阵乘指令的形态，它把 M 或 N 维度切分到两个 CTA，共享同一份权重加载。对量化推理的意义在于：权重带宽被两个 SM 分摊，单次加载服务更大计算量，权重带宽压力下降；但激活侧的逐通道缩放必须在两个 SM 间保持一致，若平滑系数按张量并行切分后的局部通道重新统计，跨卡不一致会导致两个 SM 看到不同的 s_j，等价变换被破坏。工程判断是：平滑系数必须在切分前按全局通道统计，切分后只做局部切片，不做局部重估。</p>\n<p>TMEM 的容量约束是另一个代价点：累加器驻留 TMEM 意味着同时活跃的累加块数量受限，批大小与 tile 尺寸的选择空间被压缩。举例：一个 FFN 层的 N 维度很大，若 tile 切分过细，TMEM 容纳不下足够多的累加块，内核被迫串行化，吞吐下降；此时应增大单 tile 的 K 维度让累加在 TMEM 内完成更多工作，而不是缩小 tile。第五代 Tensor Core 对 FP8 与 NVFP4 的原生支持决定了格式选择的底线：格式不被原生支持时，内核会退化为软件模拟或格式转换，带宽收益被转换开销吃掉。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-16\">十六 · 误差预算：平滑强度、量化粒度与累加三者的耦合</h3>\n<p>把误差拆成三块做预算，是部署侧调 α 与选粒度的依据。激活量化误差随 α 增大而减小（激活被压窄），权重量化误差随 α 增大而增大（权重列被放大），两者之和在某个 α 处最小，这个最优点按层不同。累加误差与 α 无关，只与 K 维度和累加器精度有关。因此调优顺序应是：先固定累加精度与格式，再按层扫 α，最后检查激活量化粒度是否与内核布局匹配。</p>\n<p>量化粒度的选择直接写进内核效率：激活逐张量量化只需一个标量缩放，内核无额外访存；按 token 分组量化需要每 token 一个缩放因子，访存增加但能吸收 token 间的动态范围差异；逐通道激活量化需要逐通道重排与缩放，访存开销最高且难以复用高吞吐路径。SmoothQuant 的立场是前两者，把逐通道自由度留给离线权重。代价是：按 token 分组量化在变长 prompt 批处理下，每组缩放因子需随 token 动态生成，若分组边界与内核 tile 边界不对齐，会出现部分 tile 跨组、缩放因子重复加载。</p>\n<p>具体例子：分离式预填与解码部署中，预填阶段一次处理长序列，激活极值统计覆盖整个 prompt，动态范围大；解码阶段逐 token 生成，激活极值分布窄。若两阶段共用一套量化参数，预填阶段校准出的 s_j 在解码阶段会过度平滑，把量化难度过多推给权重，解码阶段权重量化误差上升。正确做法是按阶段分别校准，预填与解码各持一套 s_j 与量化参数，代价是校准开销翻倍、参数量翻倍，但避免了单阶段精度塌陷。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-17\">十七 · 音频生成场景的算子映射与校准差异</h3>\n<p>音频生成推理的线性层结构与文本模型同构，但激活分布不同：声码器前馈层的输入是声学特征，动态范围随音频内容剧烈波动，短序列上方差大；注意力投影层的激活极值受自回归历史影响，长序列累积后离群通道更突出。SmoothQuant 的变换可原样套用，但 s_j 必须用音频校准集重新求，文本校准集的极值分布与音频不匹配，直接套用会让声码器输出明显失真。</p>\n<p>算子映射上，声码器前馈层通常是逐帧独立的 GEMM，批维度是帧数，激活按 token 分组量化时分组边界应与帧边界对齐，避免一帧的缩放因子跨到相邻帧。注意力投影层的 K 维度是头维度乘以头数，tcgen05 的累加在 TMEM 内完成，反量化按输出通道执行，与文本模型一致。代价点是音频帧率下的批大小通常较小，TMEM 利用率低，2-SM MMA 的收益被小批稀释，此时应优先保证单 SM 路径的累加效率而非追求双 SM 协同。</p>\n<p>失败模式在此更尖锐：用文本校准集校准音频模型，某层声码器前馈层的激活离群通道未被识别，量化后该通道溢出量化范围，输出表现为周期性失真或截断。工程上需监控逐层激活极值漂移，按层回退高精度，回退粒度是层而非整网，因为音频生成对个别层的精度敏感度远高于文本。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-18\">十八 · 内核实现判断：格式、粒度、累加三者的取舍顺序</h3>\n<p>落到工程判断，Blackwell 上部署 SmoothQuant 的取舍顺序应是：格式由张量核原生支持决定（FP8 优先，NVFP4 仅在平滑充分且校准覆盖足够时启用），粒度由内核访存模式决定（激活逐张量或按 token 分组，权重逐通道），累加精度由 K 维度与误差预算决定（长 K 必须走高精度累加器，短 K 可放宽）。α 的调优在这三者固定后进行，按层类型分组扫，不设全局常数。</p>\n<p>一个可操作的伪代码思路：对每层先读校准统计的激活逐通道极值与权重逐通道极值，按 α 网格算 s_j，对每个候选 α 估算激活量化误差与权重量化误差之和，取最小者；再检查该 α 下激活量化粒度是否与内核 tile 对齐，不对齐则调整分组边界或退回逐张量。这个流程不涉及反向传播，全部是解析计算与前向统计，属于部署侧一次性离线开销。代价是校准样本规模与领域覆盖决定极值估计稳定性，长上下文请求会放大激活极值波动，校准集必须包含长序列样本，否则 s_j 失准。</p>\n<p>最后落在具体机制上：tcgen05 的累加器驻留 TMEM 使得反量化可以推迟到累加完成后按输出通道一次性执行，这改变了量化内核的写法——不再需要在每个 K 块后插入反量化，而是把缩放因子作为累加后处理的元数据随块加载。这一机制与 SmoothQuant 的“逐通道自由度全给权重”设计正好咬合：权重缩放因子离线固化、随块进入内核，激活缩放因子在线逐 token 生成、在累加后统一施加，两者在 TMEM 侧汇合，反量化指令数随 K 块数下降而不再线性增长。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-19\">十九 · 显存账本的三个账户与比特数的线性效应</h3>\n<p>在 Blackwell 单机或 NVL72 机柜上做推理容量规划，显存不是一笔糊涂账，而是三个可分别核算的账户：权重、激活工作区、KV cache。SmoothQuant 只直接改写前两个账户的比特宽度，第三个账户需要单独决策，因为 KV cache 的量化误差会与权重/激活量化误差叠加。权重账户的规模由参数量与每参数比特数决定，W8 相对 FP16 是严格的二分之一，这一点在权重逐通道量化、缩放因子离线固化进权重布局后成立——推理时不需要在线统计，显存占用随比特数线性下降。激活账户则不是常驻的，它是前向过程中的临时峰值：矩阵乘的输出缓冲、归一化中间结果、注意力分数矩阵。把激活从 FP16 压到 W8A8 的收益体现在两处，一是峰值工作区缩小从而允许更大的 micro-batch，二是矩阵乘的读带宽需求减半。</p>\n<p>KV cache 账户最容易被低估。它的规模是：</p>\n<div class=\"formula\">$$ M_{\\text{KV}} = 2 \\cdot L \\cdot H_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot B \\cdot S \\cdot b_{\\text{kv}} $$</div>\n<p>其中 2 是 K 与 V 两份，L 是层数，H_kv 是 KV 头数（GQA/MQA 下远小于查询头数），d_head 是头维，B 是并发序列数，S 是上下文长度，b_kv 是每元素字节数。这个式子的关键含义是：KV cache 随 B×S 线性增长，而权重是常数。在小批量短上下文时权重占主导，在长上下文高并发时 KV 反超。以 70B 级模型、80 层、8 个 KV 头、128 头维为例，每 token 每序列的 KV 是 2×80×8×128×2 字节，即每 token 约 320 KB（FP16）；一条 8K 上下文的序列就是约 2.6 GB，32 条并发即 80 GB 量级——这已经逼近单卡 HBM3e 的可用容量，而此时权重按 W8 算是 70 GB。账本必须按目标 B 与 S 复算，不能沿用短上下文时代的直觉。</p>\n<p>工程代价在这里表现为一个硬约束：HBM3e 容量决定了 B×S 的上限，而 B 与 S 又共同决定吞吐。容量不足时只能降 B，降 B 直接压低矩阵乘的算术强度，把内核从计算受限推到带宽受限。所以 KV 的每元素字节数不是\"锦上添花\"的优化，而是吞吐的分水岭。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-20\">二十 · 分页：把连续假设换成块表</h3>\n<p>连续批处理的前提是 KV 按块管理而非按序列连续分配。分页 KV cache 把每条序列的 KV 切成固定 token 数的块（block），用一个块表把逻辑位置映射到物理块，块可在显存池中离散分布。这样做的直接收益是消除预留浪费：按最大长度预留会在短请求上浪费数倍显存，分页后按实际生成长度追加块，显存占用贴近真实需求。第二个收益是前缀共享——相同系统提示或相同 few-shot 前缀的请求可以指向同一批物理块，只增引用计数不复制数据，在多轮对话与 RAG 场景里这是实打实的容量节省。</p>\n<p>代价在访存侧。分页把原本连续的 KV 读变成按块表间接寻址，注意力内核需要按块 gather，块大小选小了元数据开销与 TLB 压力上升，选大了内部碎片增加。工程判断是块大小要与头维和 dtype 对齐到 2 的幂，使单块的 K 或 V 恰好是若干条 cache line 的整数倍，避免跨块边界的非对齐读。在 Blackwell 上，这条规则与 tcgen05 的 TMEM 布局、2-SM MMA 的共享访存模式耦合：注意力内核的 KV 读若不能形成规则的分块流，MMA 的流水线会出现气泡。</p>\n<p>一个具体例子：块大小取 16 token、8 个 KV 头、128 头维、FP16，单块单侧为 16×8×128×2 字节 = 32 KB，K 与 V 合计 64 KB，正好落在若干 cache line 的整数倍上，块表项可压缩为 32 位索引。若把块改成 17 token，所有对齐假设崩塌，内核退化。这就是\"分页不是数据结构课上的抽象，而是对齐约束下的工程选择\"。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-21\">二十一 · 压缩与复用：KV 的比特与结构两条路</h3>\n<p>KV 压缩有两条互不替代的路径。比特路径是把 b_kv 从 2 字节降到 1 字节甚至 4 比特，收益是线性的容量与带宽节省，代价是量化误差在长上下文上累积——注意力的 softmax 对 K 的误差敏感，V 的误差则相对温和，因此非对称量化（K 更保守、V 更激进）是常见取舍。结构路径是 GQA/MQA 减少 H_kv、或对 KV 做低秩/稀疏化，收益来自减少元素个数而非每元素比特。两条路可以叠加，但叠加后的误差不再可解析预测，必须逐层监控。</p>\n<p>这里必须把 SmoothQuant 的边界讲清楚：它的等价变换作用在线性层的输入激活与权重列上，KV cache 是注意力输出写出的张量，不在这条变换链里。把权重/激活的缩放因子直接套到 KV 上会导致误差叠加，正确做法是 KV 单独校准、单独量化，且预填阶段与解码阶段的激活极值统计不同，量化参数需按阶段分别校准，否则解码阶段精度塌陷。这是分离式预填/解码部署里最容易踩的坑：预填阶段批量大、序列长，极值统计偏向长序列分布；解码阶段逐 token、批量小，分布窄但尾部事件更突出。</p>\n<p>复用则是另一类节省。前缀共享之外，还有跨请求的 KV 复用（相同文档上下文）、以及把 KV 从 HBM 卸载到主机内存或远端存储的分层方案。卸载的代价是 PCIe 或网络往返延迟，只有在 KV 命中率高、且被卸载的块短期内不会被重新读取时才划算。带宽瓶颈的判断标准很直接：若解码阶段的每 token 时间被 KV 读主导，则瓶颈在 HBM 带宽；若被卸载回填主导，则瓶颈在互连。Blackwell 的 NVLink 5 在机柜内提供了高带宽的卡间通路，使 KV 在 NVL72 内跨卡共享成为可行选项，但这要求块表与路由策略协同，否则跨卡 gather 的延迟会吃掉共享带来的容量收益。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-22\">二十二 · 带宽瓶颈的定位：算术强度与每 token 字节数</h3>\n<p>解码阶段是典型的带宽受限。每生成一个 token，需要读一遍参与计算的权重（在 MoE 下是激活专家）加上该序列的全部 KV。算术强度可写成：</p>\n<div class=\"formula\">$$ I = \\frac{2 \\cdot P_{\\text{active}} \\cdot B}{b_w \\cdot P_{\\text{active}} + B \\cdot S \\cdot b_{\\text{kv}} \\cdot 2 L H_{\\text{kv}} d_{\\text{head}} / S} $$</div>\n<p>简化后的直觉是：分子随 B 线性增长，分母里权重项是常数、KV 项随 B 线性增长。B 很小时分母被权重项主导，I 很低，内核贴着 HBM 带宽跑；B 增大到 KV 项与权重项同量级后，I 才开始爬升。这解释了为什么连续批处理要把 B 推高——不是为了并行度本身，而是为了把算术强度推过带宽拐点。W8A8 的作用是把 b_w 减半，等价于把权重项砍半，使拐点提前到来，即在更小的 B 下就脱离带宽受限区。这是 SmoothQuant 在系统层面的真实价值：它不只是省显存，它移动了 roofline 的拐点位置。</p>\n<p>具体例子：一个 8B 稠密模型、W8 权重 8 GB、HBM3e 单卡带宽按定性表述为\"高\"，在 B=1、S=4K 时每 token 需读 8 GB 权重加约 0.5 GB KV，算术强度极低，内核完全带宽受限，token 间隔由 8.5 GB 除以带宽决定；把 B 提到 32，权重项被摊薄 32 倍，KV 项升到约 16 GB，算术强度提升但仍受限，此时若把 KV 压到 1 字节，KV 项减半，token 间隔明显下降。这条链路里每一步的收益都可复算，不需要实测数字也能判断方向。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-23\">二十三 · 可复算的显存预算模板</h3>\n<p>给出一份可直接代入的预算表。设参数量 P、权重每参数比特 b_w、层数 L、KV 头数 H_kv、头维 d_head、并发 B、上下文 S、KV 每元素比特 b_kv、激活峰值系数 k_a（相对于单层最大激活的倍数，含工作区与碎片）。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>公式</th><th>控制手段</th><th>失效后果</th></tr></thead><tbody>\n<tr><td>权重</td><td>P · b_w / 8</td><td>W8 逐通道量化，缩放因子离线固化</td><td>容量不足则降并行度或降精度</td></tr>\n<tr><td>激活峰值</td><td>k_a · B · S_max · d_model · b_a / 8</td><td>W8A8、micro-batch 切分</td><td>峰值溢出触发重算或换卡</td></tr>\n<tr><td>KV cache</td><td>2 L H_kv d_head B S b_kv / 8</td><td>分页、GQA、KV 量化、前缀共享</td><td>B 上限被压低，吞吐掉档</td></tr>\n<tr><td>运行时保留</td><td>内核工作区、通信缓冲、块表元数据</td><td>按拓扑预留固定比例</td><td>OOM 或通信阻塞</td></tr>\n</tbody></table>\n<p>复算顺序建议为：先按 SLO 定 S 与目标 B，算出 KV 账户；再用总容量减去权重与运行时保留，得到可用 KV 空间，反解出可行的 B；若 B 不满足吞吐目标，则依次尝试 KV 量化降 b_kv、前缀共享降有效 S、分页降碎片、最后才是降 S 或加卡。每一步都对应一个明确的机制，而不是拍脑袋调参。</p>\n<p>一个具体算例：P=70B、b_w=8 得权重 70 GB；L=80、H_kv=8、d_head=128、b_kv=8（KV 也压到 1 字节）得每 token 每序列 160 KB；若单卡可用 180 GB，减去权重 70 GB 与运行时保留 20 GB，剩 90 GB 给 KV，则 B×S 上限约 5.6×10^5 token。取 S=8K 得 B≈68；取 S=32K 得 B≈17。这个数字直接决定批调度器的并发上限，也决定连续批处理能否把算术强度推过拐点。若把 b_kv 留在 16 位，B 上限直接腰斩，吞吐目标落空——这就是为什么 KV 量化在长上下文部署里不是可选项。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-24\">二十四 · 校准漂移与账本的动态性</h3>\n<p>账本不是一次算完就冻结的。校准分布偏移会使某层激活极值估计失真，量化后该层激活可能超出量化范围，表现为输出重复或截断；工程上需按层回退高精度并监控逐层极值漂移。这意味着显存预算里要留一条\"回退余量\"：若若干层回退到 FP16，权重账户会小幅回升，KV 与激活账户不变，但内核路径分叉会增加调度复杂度。监控项应包括逐层激活极值漂移、量化后输出与高精度输出的余弦相似度、以及端到端首包延迟。</p>\n<p>音频生成场景是这条规则的典型反例：声码器前馈层与注意力投影层可套用同一平滑变换，但音频激活分布与文本不同，长度分布短且方差大，必须用音频校准集重新求缩放系数；用文本校准集直接校准音频模型，激活极值分布不匹配，量化后声码器输出会出现明显失真。此时账本上的显存收益是真实的，但输出质量不达标，收益不可兑现。工程判断因此落在：先确认校准集覆盖目标负载的极值尾部，再谈比特数带来的容量与带宽收益；账本算得再漂亮，校准失准就等于把预算建立在错误的分布假设上。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-25\">二十五 · 平滑之后，显存账本与 KV 边界</h3>\n<p>SmoothQuant 只改权重与激活的比特数，不触碰 KV cache 的精度策略，因此它的显存收益有明确边界。以一层线性层为例，W8A8 后权重占用按比特数线性下降，权重缩放因子离线固化进布局，推理时无需在线统计；但 KV cache 仍按原精度逐 token 增长，序列一长，KV 就会反超权重成为主占用项。可复算的账本是：<span class=\"formula\">$$ M_{\\text{total}} \\approx \\underbrace{\\frac{P_w \\cdot b_w}{8}}_{\\text{权重}} + \\underbrace{2 \\cdot L \\cdot H_{kv} \\cdot d \\cdot b_{kv} \\cdot B \\cdot T}_{\\text{KV cache}} $$</span>其中 \\(P_w\\) 为参数量、\\(b_w\\) 为权重比特、\\(L\\) 为层数、\\(H_{kv}\\) 为 KV 头数、\\(d\\) 为头维、\\(B\\) 为并发批、\\(T\\) 为上下文长度。把 \\(b_w\\) 从 16 降到 8，只压缩第一项；第二项与 \\(b_{kv}\\) 绑定，若 KV 保持高精度，长上下文下总占用下降幅度远小于权重账面收益。这正是该方案的系统代价所在：它降低矩阵乘带宽需求，却不改变 KV 的读写带宽曲线。</p>\n<p>失效条件集中在两处。其一，平滑强度 alpha 若被当作全局常数套用，部分层权重量化误差上升，需按层类型分别调优；其二，校准集分布偏移使某层激活极值失准，量化后输出重复或截断，工程上必须按层回退高精度并监控逐层极值漂移。更隐蔽的是部署形态：分离式预填与解码中，预填阶段与解码阶段的激活极值统计不同，量化参数需按阶段分别校准，否则解码阶段精度塌陷；文本校准集直接用于音频生成模型时，声码器前馈层与注意力投影层的激活分布不匹配，量化后输出明显失真。这些都不是比特数能救回来的。</p>\n<p>因此显存预算必须把 KV 单独列账，不能与权重收益混算。一个可操作的判断是：当 \\(T\\) 与 \\(B\\) 的乘积使 KV 项超过权重项时，继续压权重比特的边际收益趋近于零，此时应转向 KV 的分页、压缩或卸载，或对 KV 单独量化——但后者不能与权重激活共用缩放因子，否则误差叠加。SmoothQuant 的工程定位应视为“把激活拉回硬件友好的粗粒度量化区间”，其显存红利仅在权重主导的中短上下文区间兑现；长上下文与高并发场景下，真正的账本瓶颈在 KV 带宽与容量，而非权重比特。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-26\">二十六 · 连续批处理：把 KV cache 的碎片时间收回来</h3>\n<p>在 W8A8 之后，权重与激活的带宽压力下降，调度器暴露出来的空闲反而更明显：解码阶段每步只算一个 token，矩阵乘的算术强度低，GPU 大部分时间在等 KV cache 的读写和采样。连续批处理（continuous batching）的机制是取消“整批同进同出”的栅栏，以请求为粒度在每一步解码后重新组批：完成的序列立刻退出并释放其 KV 块，等待队列里的新请求在同一迭代边界插入。伪代码思路是：每步维护 <code>active_set</code>，先剔除 <code>finished</code> 与 <code>preempted</code>，再从 <code>waiting</code> 按优先级取请求直到 token 预算或 KV 块预算耗尽，然后统一前向。这里的约束不是批大小，而是每步的 token 预算 <code>B_tok</code> 与 KV 块预算 <code>B_kv</code>，二者共同决定这一步能装下多少条序列。</p>\n<div class=\"formula\">$$ T_{\\text{step}} \\approx \\max\\left(\\frac{B_{\\text{tok}}\\cdot d}{W_{\\text{eff}}},\\ \\frac{B_{\\text{kv}}\\cdot d}{W_{\\text{kv}}}\\right) + T_{\\text{sample}} $$</div>\n<p>其中 <code>d</code> 是每 token 需要搬运的权重与 KV 字节数，<code>W_eff</code>、<code>W_kv</code> 分别是权重与 KV 的有效带宽。量化把 <code>d</code> 压下来，<code>T_step</code> 的分子变小，固定开销 <code>T_sample</code> 与内核启动占比上升，因此连续批处理的价值从“填满算力”转为“填满采样与访存间隙”。代价是显存：活跃序列越多，KV 块占用越大，块分配器需要预留碎片余量；一旦块池耗尽，调度器只能拒绝新请求或抢占已有序列。工程判断是：在 B200 这类高带宽器件上，连续批处理的吞吐收益主要来自把解码步的批做大到采样开销可摊薄的程度，而不是把矩阵乘做大。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-27\">二十七 · Chunked prefill：把长 prompt 切成不阻塞解码的片</h3>\n<p>预填阶段是计算密集的，一条长 prompt 的 prefill 会独占整个迭代，让同批中正在解码的序列停顿数百毫秒，直接抬高尾延迟。chunked prefill 的机制是把一条 prompt 按固定 token 数切成若干 chunk，每个迭代只处理一个 chunk，并与解码 token 混批：计算密集的 chunk 与访存密集的解码步共享同一个前向，从而把 GPU 的两种资源同时喂饱。调度上需要给每个迭代设一个 token 预算，chunk 大小取预算减去当前解码 token 数，剩余预算才给新 chunk。</p>\n<p>代价体现在首包延迟（TTFT）与解码抖动（ITL）的权衡：chunk 越小，解码步被打断的次数越少，ITL 越平稳，但一条长 prompt 需要更多迭代才能完成，TTFT 上升；chunk 越大，TTFT 下降，但解码序列在 chunk 执行期间被阻塞，尾延迟变差。对 SmoothQuant 部署而言还有一个额外约束：预填与解码的激活分布不同，预填阶段激活极值受长序列影响更大，若两者共用一套按张量量化的缩放因子，解码阶段可能出现有效量化级不足。工程上按阶段分别校准量化参数，并在 chunk 边界上保持 KV cache 的写入粒度对齐块分配器，避免半块写入造成的重排。</p>\n<table class=\"mini\"><thead><tr><th>调度选择</th><th>TTFT</th><th>ITL 抖动</th><th>显存/带宽代价</th></tr></thead><tbody><tr><td>整条 prefill 独占迭代</td><td>低</td><td>高，解码被长时阻塞</td><td>KV 峰值集中，块池瞬时压力大</td></tr><tr><td>小 chunk 混批</td><td>高</td><td>低</td><td>迭代数增多，权重重复搬运次数上升</td></tr><tr><td>大 chunk 混批</td><td>中</td><td>中</td><td>单步 token 预算被 chunk 占满，解码批变小</td></tr></tbody></table>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-28\">二十八 · 优先级与抢占：尾延迟是被谁拖长的</h3>\n<p>尾延迟的来源通常不是平均吞吐不够，而是少数长序列或大 prompt 把共享资源占满。优先级调度的机制是给请求打两级标签：交互型（短输出、低 TTFT 要求）与批处理型（长输出、吞吐优先），调度器在每个迭代边界按标签排序取请求，并对交互型请求保留固定的 token 预算份额，防止被批处理流量饿死。抢占则是在 KV 块池耗尽时的兜底：选择优先级最低、已生成 token 最多的序列，将其 KV 块换出到主机内存或直接丢弃重算。</p>\n<p>两种抢占策略的代价不同。换出到主机内存需要走 PCIe，一次换出与换回的带宽开销与块大小成正比，恢复时还要重新装载，延迟尖峰明显；丢弃重算则放弃已生成的 token，用 prefill 重新计算上下文，计算量随上下文长度线性增长，但省掉了主机内存往返。工程判断是：短上下文序列适合重算，长上下文序列适合换出，因为重算的代价随长度增长而换出的代价只与块数有关。抢占本身会破坏 SmoothQuant 的量化稳定性——被抢占序列恢复后，其激活极值统计若已过期，按张量量化的缩放因子可能不再覆盖新的动态范围，表现为输出重复或截断，因此监控逐层激活极值漂移并按层回退高精度是必要的兜底。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-29\">二十九 · 分离式预填/解码：把两种负载放到不同资源池</h3>\n<p>预填是计算密集、解码是访存密集，二者混在同一张卡上会互相争抢 SM 与带宽。分离式部署（disaggregated prefill/decode）的机制是把预填实例与解码实例分成两个池，预填完成后把 KV cache 通过高速互联传给解码池。NVLink 5 与 NIXL 这类传输层的作用是把 KV 块的搬运做成可重叠的异步操作：预填实例在计算下一个 chunk 时，上一个 chunk 的 KV 块已经在向解码实例传输，传输延迟被计算掩盖。</p>\n<div class=\"formula\">$$ T_{\\text{req}} \\approx T_{\\text{prefill}} + \\frac{S_{\\text{kv}}}{W_{\\text{link}}} + N_{\\text{out}}\\cdot T_{\\text{decode}} $$</div>\n<p>其中 <code>S_kv</code> 是 KV 字节数，<code>W_link</code> 是互联有效带宽，<code>N_out</code> 是输出 token 数。量化在这里的作用是双重的：W8A8 降低预填阶段的权重带宽压力，KV cache 若单独量化则直接缩小 <code>S_kv</code>，把传输项压下去。代价是资源配比：预填池与解码池的算力比例需要按目标负载的 prompt 长度与输出长度分布来定，比例失配会让一侧空闲、另一侧排队，尾延迟由排队最长的那一侧决定。分离式还带来一个校准问题：预填与解码的激活分布不同，量化参数需按阶段分别校准，共用一套参数会让解码阶段精度塌陷。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-30\">三十 · 时延与吞吐的取舍：用预算而不是平均值来定容量</h3>\n<p>吞吐与延迟不是同一条曲线上的两个点，而是由调度器的预算参数决定的族。给定 SLO（例如 TTFT 与 ITL 的分位数上限），容量规划要解的是：在满足分位数约束的前提下，最大化每 GPU 的 token 吞吐。机制上，这等价于为每个迭代选择 token 预算与批组成，使得解码步的批足够大以摊薄采样与内核启动开销，同时 chunk 足够小以不让交互型请求的 ITL 越界。工程上常用的做法是把 SLO 转成预算：TTFT 上限决定单条 prompt 的最大 chunk 数与预填池的并发度，ITL 上限决定每步允许的最大 chunk 占比。</p>\n<p>尾延迟的压制靠三件事叠加：连续批处理消除整批栅栏带来的长停顿；chunked prefill 把长 prompt 的计算切成不阻塞解码的片；优先级与抢占保证交互型请求在资源紧张时仍有预算份额。量化在这一层的贡献是把 <code>T_step</code> 的分子压小，让同样的 token 预算在更短时间内完成，从而在相同 SLO 下容纳更大的批。但量化不是免费的：平滑强度按层调优不当会让某些层权重量化误差上升，表现为输出质量下降而非延迟变化，这类失败不会出现在延迟指标上，只能靠逐层余弦相似度监控捕获。最终落在具体机制上：调度器的每个预算参数都对应一个可观测的分位数指标，容量规划就是把预算调到分位数刚好达标的位置，而不是把平均值调到最好看的位置。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-31\">三十一 · 量化参数在调度面上的耦合：连续批处理、chunked prefill 与分离式部署的边界</h3>\n<p>把 SmoothQuant 放进真实推理服务，量化本身不再是离线一次性动作，而会与批调度产生耦合。连续批处理（continuous batching）在每个解码步动态拼批，同一批内不同请求的 token 位置、上下文长度与阶段（预填或解码）各不相同；若激活按 token 分组量化，则每步的缩放因子随拼批结果变化，内核需在每次迭代重新读取分组缩放并做重排。代价直接落在解码步的固定开销上：解码阶段每步只产出少量 token，矩阵乘的算术强度本就低，额外的缩放读取与重排会把这一步从带宽受限推向访存受限，尾延迟随之抬升。chunked prefill 把长 prompt 切成固定大小的块与解码请求混跑，缓解预填对解码的阻塞，但它使同一迭代内同时存在大块激活与小批解码激活，逐张量量化的缩放因子被大块激活主导，解码请求的有效量化级被压缩——这正是 SmoothQuant 要解决的离群通道问题在调度层面的翻版。工程判断是：预填块与解码批应各自持有独立的量化参数与缩放路径，而不是共用一套逐张量因子。</p>\n<p>优先级与抢占把这一耦合推到极限。当高优先级请求到达而显存不足以容纳其 KV cache 时，调度器会抢占低优先级请求、回收其 KV 块并在稍后重算。重算意味着该请求的预填被重新执行，激活极值重新统计；若量化参数在抢占前后不一致，重算路径与原始路径的输出会出现数值漂移，表现为重复或截断——这与校准分布偏移导致的失败模式同源，只是触发者从输入分布变成了调度决策。设一次抢占重算的代价为 <span class=\"formula\">$$T_{\\text{recompute}} \\approx \\frac{L_{\\text{ctx}}}{B_{\\text{chunk}}}\\cdot t_{\\text{prefill}} + t_{\\text{kv\\_restore}}$$</span>，其中分块数由 chunk 大小决定，KV 恢复受带宽约束；抢占越频繁，重算占比越高，尾延迟的方差越大。可控的做法是把量化参数按层固化、与请求无关，使重算路径复用同一组缩放因子，从而让抢占只付出计算代价而不引入数值不一致。</p>\n<p>分离式预填/解码（disaggregated prefill/decode）进一步暴露了按阶段校准的必要性。预填节点处理长上下文、激活动态范围大，解码节点处理单 token、激活极值窄；两侧若共用一套由预填统计出的平滑系数与量化参数，解码阶段的激活会被过度平滑，量化难度被推给权重，权重量化误差在低算术强度的解码内核上被放大。因此预填与解码应各自校准：预填侧侧重激活极值覆盖，解码侧侧重权重误差与分组粒度。代价是两套参数带来额外的显存与传输开销——量化参数与缩放因子需随 KV cache 或中间张量在 NVLink 上搬运，参数量虽小但破坏了参数常驻的假设。下表给出三种调度形态下量化决策的侧重：</p>\n<table class=\"mini\"><thead><tr><th>调度形态</th><th>量化粒度选择</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>连续批处理</td><td>按 token 分组，避免逐张量被长请求主导</td><td>每步缩放读取与重排，解码步开销上升</td><td>拼批内长度方差过大，分组因子频繁失效</td></tr><tr><td>chunked prefill</td><td>预填块与解码批分离参数</td><td>双路径内核，预填块边界处额外同步</td><td>块过大使解码批有效量化级骤降</td></tr><tr><td>分离式部署</td><td>预填、解码分别校准</td><td>参数跨节点传输，常驻假设被打破</td><td>共用参数致解码阶段权重误差累积</td></tr></tbody></table>\n<p>尾延迟的压制最终落在“参数稳定性”而非“调度技巧”上。SmoothQuant 的平滑强度 alpha 是逐层旋钮，若把它与批大小、序列长度联动，等于让量化参数随负载漂移，任何一次负载突变都会触发精度回退；反之，把 alpha 与量化参数在部署时按层固化、只允许在监控到逐层激活极值漂移超阈值时按层回退高精度，则调度器可以自由拼批与抢占而不必担心数值面。这与 KV cache 单独量化、不与权重激活共用缩放因子的原则一致：调度面追求的是参数不变，量化面追求的是分布可覆盖，两者交汇处就是按层回退这一条工程底线。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-32\">三十二 · 切分维度与通信原语的对应关系</h3>\n<p>在 Blackwell 机柜级部署里，并行策略不是抽象选择，而是直接决定哪条链路承载流量。张量并行（TP）把同一层的权重矩阵按列或行切开，每层前向需要一次 All-Reduce 把各卡的局部和归并；流水并行（PP）按层段切分，卡间只传激活张量，属于点对点；专家并行（EP）把 MoE 的专家分散到不同卡，token 需按路由结果重排，走 All-to-All；数据并行（DP）在推理侧通常表现为多副本负载均衡，副本之间除权重加载外几乎不通信。四者的通信量级差异极大：TP 的 All-Reduce 与隐藏维度和批大小成正比且每层都发生，PP 的激活传输只在段边界发生，EP 的 All-to-All 量随路由稀疏度与专家分布倾斜而波动。</p>\n<p>把 SmoothQuant 的量化切分放进这个框架，会暴露一个容易被忽略的约束：平滑系数是逐输入通道定义的，而 TP 按列切权重时，每个卡只持有部分输入通道，缩放向量必须按切分后的局部通道重新统计，否则跨卡拼接后的等价变换不再成立。工程上的做法是在校准阶段就按目标并行度做局部极值统计，把缩放因子随权重分片一起固化，避免推理时在线归约。代价是校准从一次性离线开销变成按拓扑重复的离线开销，拓扑变更即需重校准。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>通信原语</th><th>触发频率</th><th>主要代价</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>每层每 token</td><td>延迟敏感，受 NVLink 带宽与环/树算法深度约束</td></tr><tr><td>PP</td><td>点对点 Send/Recv</td><td>段边界</td><td>激活张量显存驻留与气泡</td></tr><tr><td>EP</td><td>All-to-All</td><td>每 MoE 层</td><td>路由倾斜导致尾部卡等待</td></tr><tr><td>DP</td><td>无（副本独立）</td><td>—</td><td>权重副本显存与加载带宽</td></tr></tbody></table>\n<p>一个具体例子：在 GB200 NVL72 的单机柜内，TP 组通常落在同一 NVLink 域，All-Reduce 走 NVSwitch 全互联，跳数固定；而跨机柜的 PP 段边界若落在 InfiniBand 上，激活传输的延迟会从微秒级跳到数十微秒级，段划分必须让边界尽量落在域内。这就是为什么 PP 的段数在机柜级部署里往往被压到很小。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-33\">三十三 · NVLink 5 与 NVSwitch：把 All-Reduce 压进计算阴影里</h3>\n<p>Blackwell 世代的 NVLink 5 提供更高的单链路带宽，配合 NVSwitch 使机柜内任意两卡之间等跳数通信，消除了早期拓扑里跨交换机跳数不均带来的长尾。对推理的直接意义是：TP 的 All-Reduce 延迟不再随卡数呈明显的阶梯式上升，环算法与树算法的选择空间变大。工程判断的依据是消息大小——小消息用树形或递归倍增降低深度，大消息用环形摊薄带宽，而 NVSwitch 的全互联让两种算法都能拿到接近峰值的有效带宽。</p>\n<p>通信能否被隐藏，取决于计算时间与通信时间的比值。对一层线性变换，设批大小为 \\(B\\)、序列长度为 \\(S\\)、隐藏维为 \\(H\\)、TP 度为 \\(N\\)，则单卡计算量约为 \\(2BSH^2/N\\) 次浮点运算，All-Reduce 需搬运的字节数约为 \\(2BSH\\) 乘以每元素字节数 \\(b\\)。二者比值给出算术强度意义上的判据：</p>\n<div class=\"formula\">$$ \\frac{T_{\\text{comm}}}{T_{\\text{comp}}} \\approx \\frac{2BSH\\,b\\,/\\,W_{\\text{nvlink}}}{2BSH^2\\,/\\,(N\\cdot F)} = \\frac{b\\,N\\,F}{H\\,W_{\\text{nvlink}}} $$</div>\n<p>其中 \\(F\\) 为单卡有效算力，\\(W_{\\text{nvlink}}\\) 为有效链路带宽。这个式子说明：隐藏维越大、TP 度越小，通信占比越低；而量化把 \\(b\\) 从 16 比特压到 8 比特，直接把通信时间减半——这是 SmoothQuant 类 W8A8 在并行部署里被低估的收益，它同时削减了矩阵乘带宽与集合通信字节数。反过来，当 \\(H\\) 较小（例如音频生成模型里声码器的前馈层隐藏维远小于语言模型），TP 的通信占比会显著上升，此时把 TP 度调大反而恶化延迟。</p>\n<p>代价面：NVLink 域的功耗与散热在机柜级预算里占比不低，全互联交换芯片的常驻功耗是固定开销；而 TP 度增加会同步增加权重分片的加载次数与显存碎片。一个具体例子是注意力投影层——它的隐藏维固定，若把 TP 度从 2 提到 8，单卡计算量降到四分之一，但 All-Reduce 字节数只降到四分之一而延迟因算法深度增加未必同比例下降，端到端首包延迟可能不降反升。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-34\">三十四 · All-to-All 与 EP：路由倾斜才是真瓶颈</h3>\n<p>专家并行的通信形态与 TP 完全不同。每个 token 经门控网络选出若干专家，这些专家分布在不同卡上，于是需要一次 All-to-All 把 token 送到目标卡、算完再送回来。通信量正比于被路由的 token 数乘以隐藏维，但真正的瓶颈不是平均带宽而是倾斜：热门专家所在卡收到的 token 远多于均值，其余卡空等。这种尾部等待在批内无法靠增加批大小摊薄，因为倾斜是分布性的。</p>\n<p>量化在这里的作用是双向的。一方面，把 token 激活压到 8 比特使 All-to-All 的字节数减半，直接缩短传输时间；另一方面，EP 场景下每个专家看到的激活分布不同，若整网共用一套平滑系数，冷门专家的激活极值估计会失准。工程做法是按专家分组校准，或对路由频率低的专家回退更高精度。伪代码思路如下：</p>\n<ul>\n<li>门控输出路由权重与目标专家索引；</li>\n<li>按目标卡聚合 token，形成发送缓冲，缓冲元素为量化后的激活加缩放因子；</li>\n<li>All-to-All 交换，接收侧按本地专家解量化；</li>\n<li>专家前向完成后反向 All-to-All 送回，按原 token 位置散射合并。</li>\n</ul>\n<p>代价判断：All-to-All 的延迟对消息大小敏感，小批量解码阶段每 token 只路由到少数专家，消息碎片化严重，此时通信延迟主导而非带宽主导；预填阶段批量大、消息连续，带宽主导。这解释了为什么分离式预填/解码部署里，EP 的拓扑与量化参数需要按阶段分别配置——预填阶段可以承受更大的 TP/EP 度以换吞吐，解码阶段则应压缩并行度以压低单 token 延迟。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-35\">三十五 · NIXL 传输与分离式部署的通信账</h3>\n<p>分离式预填/解码把计算拆到两组卡上，KV cache 需从预填节点传到解码节点。NIXL 这类传输层的作用是把 KV cache 的搬运从应用层显式拷贝变成点对点直接传输，绕开中间缓冲，降低显存占用与拷贝延迟。这里的通信账与 TP 的 All-Reduce 性质不同：它是单向、大块、按层发生的传输，量正比于上下文长度乘以 KV 头维度乘以层数乘以每元素字节数。</p>\n<p>量化对这条链路的影响最直接：KV cache 若保持高精度，传输字节数是权重激活量化的数倍，成为分离式部署的绝对瓶颈。把 KV cache 单独量化可以把传输量按比特数比例压缩，但必须与权重激活量化分开校准——共用缩放因子会让误差叠加，表现为长上下文下输出重复或截断。工程判断是：KV 量化的粒度应按头或按 token 分组，与解码内核的访存布局对齐，否则解量化时的重排开销会抵消传输收益。</p>\n<p>一个具体例子：长上下文请求在预填节点产生大量 KV，若传输链路带宽有限，解码节点会在每个 decode step 前等待 KV 到位，首包延迟被传输主导。此时把预填与解码放在同一 NVLink 域内可让传输走机柜内高带宽链路，跨域则必须依赖 NIXL 的异步流水——预填按层产出 KV、传输与解码计算重叠，用流水掩盖传输延迟。代价是解码节点需要额外的 KV 缓冲深度，显存占用上升。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-36\">三十六 · 通信何时成为瓶颈：三个可操作的判据</h3>\n<p>判据一，看计算通信比。用第二节的比值式估算：当 \\(bNF/(HW)\\) 接近或超过一，通信不再是阴影里的开销而是主导项。量化降低 \\(b\\) 是把这个比值往下压的最直接手段，但降低 TP 度 \\(N\\) 同样有效，且不引入数值误差。</p>\n<p>判据二，看批形态。预填阶段 \\(B\\cdot S\\) 大，计算时间长，通信易被掩盖；解码阶段每步只处理一个 token，计算时间极短，All-Reduce 的固定延迟无法被掩盖，此时 TP 度是纯负担。这就是解码侧倾向更小 TP 度、更大 DP 副本的原因——用副本并行换单请求延迟。</p>\n<p>判据三，看拓扑边界。同一 NVSwitch 域内的集合通信与跨域通信延迟差一个量级以上，任何把高频通信放在跨域链路上的切分都是设计错误。PP 的段边界、EP 的专家放置、分离式部署的 KV 传输路径，都应优先落在域内。</p>\n<p>代价面汇总：通信瓶颈的显性代价是首包延迟与解码吞吐，隐性代价是显存——为掩盖传输而增加的缓冲深度、为对齐内核布局而做的重排缓冲，都会吃掉量化省下来的显存。一个具体例子是音频生成推理：声码器前馈层隐藏维小、序列短，TP 的通信占比高，工程上更倾向单卡放下整个声码器、用 DP 扩副本，而不是切 TP；同时用音频校准集重新求平滑系数，避免文本校准的极值分布失配导致量化后失真。</p>\n<p>最终落到机制上：并行切分的通信代价由原语类型、消息大小与拓扑距离三者共同决定，而量化通过压缩每元素字节数同时作用于矩阵乘带宽与集合通信字节数——但它不改变通信的固定延迟部分，也不改变路由倾斜带来的尾部等待。因此在 Blackwell 上做推理部署时，正确的顺序是先按拓扑距离定切分边界、再按批形态定并行度、最后用量化压缩剩余带宽需求，并把平滑系数的校准与切分后的局部通道绑定，避免跨卡等价变换失配。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-37\">三十七 · 量化参数在并行切分与通信拓扑上的边界</h3>\n<p>SmoothQuant 的平滑系数是<strong>按输入通道</strong>定义的，而张量并行（TP）恰好把权重按输出维或输入维切开：一旦 <code>diag(s)</code> 的通道索引跨卡分布，各 rank 只能看到自己那一段激活极值，独立求出的 s 在 All-Reduce 归约后不再等价于单卡变换，层输出出现系统性偏差。工程做法是在校准阶段就按切分后的局部通道统计极值，并让平滑系数随权重分片一起固化进 checkpoint，使推理时无需跨卡同步统计量。流水并行（PP）则把层间边界变成激活的传输点，PP 微批的激活在 NVLink 5 上以高带宽搬运，但量化后的激活若在边界处被反量化再序列化，通信量按比特数下降的收益会被反量化开销吃掉；EP 的 All-to-All 更敏感，MoE 路由后的 token 在专家间乱序重排，逐 token 分组的激活量化参数必须随 token 一起搬运，否则接收端无法复现缩放。</p>\n<p>通信何时成为瓶颈，可以用一个粗粒度的判据刻画。设单层矩阵乘的计算量为 <code>2·B·T·d_in·d_out</code>，TP 每层需两次 All-Reduce，每次搬运 <code>B·T·d_out</code> 个元素，则计算通信比近似为：</p>\n<div class=\"formula\">$$ \\frac{C}{M} \\approx \\frac{2\\,d_{in}}{\\text{bytes per element} \\times \\text{collective count}} $$</div>\n<p>W8A8 把 bytes per element 从 2 压到 1，等于把这个比值翻倍，通信相对变贵——量化省下的带宽红利在 TP 度较大、<code>d_in</code> 较小的层上会被集合通信抵消。典型例子是 NVL72 机柜内 8 卡 TP 的解码阶段：单 token 的 GEMM 是访存受限的瘦矩阵，All-Reduce 延迟与内核启动开销占比上升，此时应优先保证量化内核与通信 kernel 的重叠（把反量化后的归约放进同一 stream），而不是继续加大 TP 度。NIXL 这类点对点传输用于分离式预填/解码时，KV cache 与激活的跨节点搬运同样受比特数影响，但预填与解码两阶段激活极值分布不同，量化参数须分阶段校准，否则解码侧会因缩放失配而精度塌陷。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>量化参数的可见范围</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>局部通道，随分片固化</td><td>跨卡独立统计后归约，等价性破坏</td></tr><tr><td>PP</td><td>层边界反量化点</td><td>边界反量化抵消带宽收益</td></tr><tr><td>EP</td><td>随 token 携带分组缩放</td><td>重排后缩放参数丢失</td></tr></tbody></table>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-38\">三十八 · 精度塌陷的三种可辨识形态</h3>\n<p>SmoothQuant 的等价变换本身不改变层输出，塌陷只发生在量化误差被放大到不可接受的时候。工程上要区分三种形态，因为它们的定位路径完全不同。第一种是<strong>单层溢出</strong>：某层激活在推理时超出校准期统计的极值范围，量化后饱和，表现为输出重复 token 或句子被截断。第二种是<strong>权重侧误差累积</strong>：平滑强度 alpha 偏大，激活被压得过狠，量化难度整体转移到权重，逐通道权重量化步长变粗，误差沿残差流逐层叠加，表现为长输出逐渐跑题而非突然崩坏。第三种是<strong>粒度错配</strong>：激活按 token 分组量化时，组内若混入一个离群 token，该组缩放因子被拉大，其余 token 有效比特骤降，表现为批内个别请求质量骤降、其余请求正常——这是最难定位的一种，因为端到端指标被平均值掩盖。</p>\n<p>诊断的抓手是逐层余弦相似度与逐层激活极值漂移两个量。对每层线性输出，比较低精度结果与高精度参考的余弦相似度 <span class=\"inline-math\">cos(y_q, y_ref)</span>；同时记录推理期逐通道最大绝对值相对校准期统计值的比值 <span class=\"inline-math\">r_j = max|X_{:,j}|_{runtime} / max|X_{:,j}|_{calib}</span>。当某层 <span class=\"inline-math\">r_j</span> 显著大于 1 且该层余弦相似度同步下降，基本可判定为单层溢出，处理方式是仅对该层回退高精度或重新收紧该通道的平滑系数。当所有层 <span class=\"inline-math\">r_j</span> 平稳而余弦相似度逐层缓慢下滑，则是权重侧误差累积，应下调 alpha 或对权重改用更细粒度量化。</p>\n<div class=\"formula\">$$ \\text{drift}_j = \\frac{\\max_{t}|X_{t,j}|_{\\text{runtime}}}{\\max_{t}|X_{t,j}|_{\\text{calib}}},\\qquad \\text{flag}_j = \\mathbb{1}\\left[\\text{drift}_j &gt; \\tau \\wedge \\cos(\\mathbf{y}_q,\\mathbf{y}_{\\text{ref}})_\\ell &lt; \\kappa\\right] $$</div>\n<p>代价上，逐层余弦相似度需要保留一份高精度参考输出，显存开销按层输出大小计；工程折中是只对疑似层做在线参考计算，其余层仅记录极值漂移这一廉价标量。极值漂移统计本身几乎零成本，因为激活在量化前必然要过一遍求最大值，把它顺手写进监控环形缓冲即可。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-39\">三十九 · OOM 与显存账本的错位</h3>\n<p>SmoothQuant 降低的是权重与激活的比特数，但推理显存的大头往往是 KV cache，两者不是同一本账。典型 OOM 现场是：权重按 W8A8 压下来后，团队把批大小调大，结果 KV cache 随批大小与上下文长度线性膨胀，反而先撞墙。KV cache 字节数近似为 <span class=\"inline-math\">\\(2 \\times L \\times H_{kv} \\times d \\times B \\times S \\times b_{kv}\\)</span>（层数、KV 头数、头维、批、序列长、每元素字节），它与权重量化档位无关，只受 KV 量化策略影响。因此“量化后显存应该够”这个直觉在长上下文场景经常失效。</p>\n<p>定位方法是把显存拆成四本账分别监控：权重常驻、激活工作区（含量化临时缓冲）、KV cache 池、框架与通信缓冲。激活工作区在 SmoothQuant 下有一处容易忽略的增量——激活先乘平滑系数再量化，需要一块与激活同形的临时缓冲，若内核未做原地复用，这块缓冲会随批大小与序列长度放大。OOM 发生时先看是哪本账越界：权重常驻在启动后就固定，越界只可能是配置错误；激活工作区越界通常伴随批大小或序列长度的阶跃；KV cache 池越界则表现为随请求累积缓慢爬升直至拒绝服务。</p>\n<table class=\"mini\"><thead><tr><th>显存账本</th><th>随什么增长</th><th>与 SmoothQuant 的关系</th><th>越界典型症状</th></tr></thead><tbody><tr><td>权重常驻</td><td>模型规模、比特数</td><td>直接受益，随比特线性下降</td><td>启动即失败</td></tr><tr><td>激活工作区</td><td>批大小 × 序列长</td><td>平滑临时缓冲引入额外同形块</td><td>批调大后阶跃式 OOM</td></tr><tr><td>KV cache 池</td><td>批 × 上下文 × KV 头数</td><td>不受权重档位影响</td><td>请求累积后缓慢爬升</td></tr><tr><td>通信/框架缓冲</td><td>并行度、NCCL 通道</td><td>缩放因子按切分后局部通道统计</td><td>多卡扩展时出现</td></tr></tbody></table>\n<p>具体例子：张量并行切分后，若缩放因子仍按切分前的全局通道统计，各卡拿到的局部通道极值与全局不一致，量化参数在卡间失配，表现为某几张卡输出偏差、整体精度下降而非 OOM——这类问题在显存账本上查不到，必须靠逐卡逐层余弦相似度对齐才能发现。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-40\">四十 · 批抖动与尾延迟</h3>\n<p>连续批处理下，批的组成每个调度周期都在变，量化内核的有效性也随之抖动。抖动来源有三：一是批内序列长度方差大，按 token 分组量化时短序列与长序列混在一组，组内极值由最长序列主导；二是新请求进入时预填阶段的激活极值与解码阶段不同，若两阶段共用一套量化参数，解码阶段的激活分布偏移会造成精度抖动；三是批大小跨越内核 tile 边界时，矩阵乘内核从高吞吐路径切到边界处理路径，单步延迟出现台阶。</p>\n<p>尾延迟的量化表达是分位数而非均值。设单步延迟分布 <span class=\"inline-math\">T</span>，SLO 通常约束 <span class=\"inline-math\">\\(P99(T) \\le T_{\\text{slo}}\\)</span>，而批抖动会让 P99 与 P50 的比值显著拉开。诊断上要把延迟按“批组成特征”分桶：批内最大序列长、批内长度方差、是否含预填请求。若 P99 集中在“含预填请求的混合批”桶，说明预填与解码的资源竞争是主因，应考虑分离式预填/解码而非继续调量化参数；若 P99 集中在“长度方差大的批”桶，则是分组量化的组内极值问题，应改为按 token 分组并对组大小设上限。</p>\n<div class=\"formula\">$$ \\text{jitter} = \\frac{P99(T) - P50(T)}{P50(T)},\\qquad \\text{SLO}_{\\text{ok}} = \\mathbb{1}\\left[P99(T)\\le T_{\\text{slo}} \\wedge P99(\\text{quality})\\ge q_{\\text{slo}}\\right] $$</div>\n<p>代价判断：批抖动本身不增加显存，但会迫使调度器保守地限制批大小以压尾延迟，直接损失吞吐。一个可操作的工程判断是——当 jitter 超过设定阈值时，优先拆分混合批而不是降低量化档位，因为量化档位下调带来的精度收益远小于批拆分带来的尾延迟收益。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-41\">四十一 · 静默降级：没有报错的精度流失</h3>\n<p>最危险的失败模式不报错。量化内核不会因为激活溢出而抛异常，它只是饱和；权重误差不会触发断言，它只是让输出缓慢偏离。静默降级的典型链路是：校准集领域覆盖不足 → 某层离群通道未被识别 → 该通道平滑系数偏小 → 推理时该通道激活溢出 → 输出重复或截断，但服务层只看到“请求成功返回”。</p>\n<p>监控静默降级需要独立于服务健康检查的质量探针。可行做法是维护一小批固定探针请求，周期性（按请求数或时间）重放，把输出与高精度参考做相似度比对，同时记录逐层极值漂移的滑动统计。探针请求应覆盖目标部署的上下文长度分布与领域分布，尤其是长序列样本——长上下文会放大激活极值波动，是校准失准的高发区。对音频生成场景，探针必须是音频校准集前向，因为音频激活分布与文本不同，用文本探针监控音频模型会漏掉声码器前馈层的失真。</p>\n<p>工程代价：探针请求占用少量算力与显存，且需要保留高精度参考路径（可以是离线预计算的参考输出，避免在线跑高精度）。逐层极值漂移的滑动统计只需标量存储，代价可忽略。真正昂贵的是高精度参考输出的存储与版本管理——模型或校准集更新后参考必须同步重算，否则探针会把版本差异误报为精度降级。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-42\">四十二 · 定位与回滚的工程路径</h3>\n<p>定位应按“从粗到细”的顺序收敛，避免一上来就逐层比对。第一步看端到端质量探针是否越线，越线则进入第二步；第二步看逐层余弦相似度，找出相似度最低的若干层；第三步对这些层看极值漂移 <span class=\"inline-math\">drift_j</span>，区分是溢出（drift 大）还是权重误差（drift 平稳）；第四步按判定结果分别处置——溢出层回退高精度或重算该通道平滑系数，权重误差层下调 alpha 或改权重粒度。</p>\n<p>回滚粒度必须是按层而非整网。整网回退高精度会把 SmoothQuant 的显存与带宽收益全部丢掉，而实际出问题的往往只是少数层。按层回退的实现方式是在推理图里为指定层挂高精度分支，其余层保持 W8A8，混合精度图的调度开销很小，因为层间边界本来就是同步点。回滚触发条件应写成自动化规则：当某层余弦相似度连续若干监控周期低于阈值，自动切到高精度分支并告警，而不是等人发现输出异常。</p>\n<ul>\n<li>校准侧：按层类型分别调 alpha，注意力投影层与全连接层的激活分布不同，套用同一常数会让部分层权重量化误差上升。</li>\n<li>部署侧：预填与解码阶段分别校准量化参数，避免解码阶段精度塌陷。</li>\n<li>并行侧：缩放因子按张量并行切分后的局部通道重新统计，避免跨卡不一致。</li>\n<li>监控侧：逐层极值漂移、逐层余弦相似度、端到端首包延迟三项并列，缺一项就会漏掉一类失败模式。</li>\n</ul>\n<p>最后落在具体机制上：回滚的正确单位是“层 × 阶段 × 并行分片”的三元组，而不是层。同一层在预填阶段可能因长序列激活极值大而需要高精度，在解码阶段却可以安全地保持 W8A8；同一层在不同张量并行分片上拿到的局部通道极值也不同。把回滚决策绑定到这个三元组，才能在不牺牲整体收益的前提下掐掉精度塌陷的源头。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-43\">四十三 · 失效链与灰度回退：从极值漂移到静默降级的定位手法</h3>\n<p>SmoothQuant 的失效不是单点崩溃，而是一条链：校准极值失真 → 某层激活越界 → 量化饱和 → 输出重复或截断。定位的第一步是把“离线一次性开销”变成可追溯的指纹：校准阶段除固化权重逐通道缩放因子外，应同时落盘每层激活的逐通道最大绝对值向量与平滑系数 s_j，推理侧按批周期性采样同一层的激活极值，计算漂移比 <span class=\"formula\">$$ \\rho_j = \\frac{\\max(|\\mathbf{X}^{\\text{online}}_{:,j}|)}{\\max(|\\mathbf{X}^{\\text{calib}}_{:,j}|)} $$</span> 一旦某通道 ρ_j 越过量化范围上限对应的阈值，该层即进入高风险集合。代价是采样本身要读一遍激活，对带宽敏感的解码阶段属于额外开销，因此只对风险层开启、按固定请求间隔抽样，而非全量常开。</p>\n<p>批抖动与尾延迟往往同源：变长 prompt 使按 token 分组量化的分组边界随批组成变化，同一层在不同批下激活极值不同，量化参数若按批静态复用就会在长上下文请求上失准。工程判断是把量化参数与批解耦——权重缩放离线固化，激活缩放按 token 分组在线求，避免“小批校准、大批推理”的错配。分离式预填/解码部署中预填与解码的激活分布不同，必须按阶段分别校准，否则解码阶段会出现不易察觉的精度塌陷：首包正常、后续 token 逐渐劣化，属于典型静默降级。</p>\n<p>监控项应覆盖三层：逐层激活极值漂移 ρ_j、量化输出与高精度参考的余弦相似度、端到端首包延迟与 token 间延迟的 P99。回退策略按层粒度而非整网：命中高风险集合的层切回高精度，其余层保留 W8A8，用一张按层开关表驱动推理图。下表给出失效模式与处置的对应关系。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>根因</th><th>处置</th></tr></thead><tbody><tr><td>输出重复/截断</td><td>激活越界饱和</td><td>该层回退高精度，重校准</td></tr><tr><td>解码期缓慢劣化</td><td>预填/解码共用缩放</td><td>按阶段分别校准</td></tr><tr><td>显存未降反升</td><td>逐通道激活量化引入重排缓冲</td><td>改回逐张量或按 token 分组</td></tr><tr><td>声码器失真</td><td>文本校准集分布不匹配</td><td>用音频校准集重求 s_j</td></tr></tbody></table>\n<p>OOM 的诱因常被误判为权重未压：真正占坑的是为逐通道激活量化准备的临时重排与缩放缓冲，以及回退层保留的高精度副本。容量规划时须把回退预算计入显存上限，否则灰度期间整网 W8A8 与部分高精度层并存会触发 OOM。平滑强度 alpha 也不应当作全局常数：过度平滑把量化难度推给权重，逐层权重量化误差上升，表现为某些层余弦相似度下降而激活极值正常——这类失效只能靠逐层相似度监控捕获，端到端指标看不出来。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-44\">四十四 · 基准口径的三层结构：模型、硬件档位、负载</h3>\n<p>读 SmoothQuant 这类量化工作的性能数字，第一件事不是看倍数，而是把口径拆成三层：模型层（参数量、层类型、是否含 MoE、注意力头配置）、硬件档位（目标 GPU 的整数或低精度张量核能力、显存带宽、是否多卡张量并行）、负载层（batch、并发、prompt 与 decode 长度分布）。三层任一不同，数字就不可直接比较。Blackwell 上尤其如此：SM100/SM103 的低精度张量核与 TMEM 累加布局决定了 W8A8 内核能否真正跑满，同一份量化权重在支持粗粒度激活量化的内核上和在需要额外重排的内核上，端到端延迟可以差出一个量级。因此基准表必须显式标注这三层，缺一层就等于没有口径。</p>\n<p>机制上，量化收益来自两条独立的带宽削减路径：权重显存占用随比特数线性下降，矩阵乘的权重访存带宽同比例下降；激活量化则削减中间张量的读写带宽。前者与硬件档位弱相关（只要显存够），后者强相关——激活逐张量或按 token 分组量化能复用高吞吐矩阵乘内核，逐通道激活量化则需额外重排与缩放，访存开销上升，抵消显存收益。这就是为什么同一模型在不同 GPU 档位上，W8A8 的加速比不可比：瓶颈可能从权重带宽转移到激活重排开销。</p>\n<div class=\"formula\">$$ T_{\\text{layer}} \\approx \\max\\left(\\frac{B_{W}}{BW_{\\text{HBM}}},\\ \\frac{B_{A}}{BW_{\\text{HBM}}}\\right) + T_{\\text{requant}},\\quad B_{W}\\propto \\frac{P\\cdot b_w}{8},\\ B_{A}\\propto \\frac{T\\cdot H\\cdot b_a}{8} $$</div>\n<p>其中 $b_w$、$b_a$ 为权重与激活位宽，$T_{\\text{requant}}$ 是量化/反量化与重排的固定开销。工程判断：当 $T_{\\text{requant}}$ 占比超过矩阵乘时间的两成，W8A8 的端到端收益就被吃掉，此时应优先保证激活量化粒度与内核布局匹配，而不是继续压位宽。具体例子：某线性层权重 4096×4096、batch 下 token 数 512、隐藏维 4096，权重访存与激活访存在 8 比特下同量级，若激活走逐通道量化引入重排，该层延迟可能不降反升——这正是基准必须分档报告的原因。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-45\">四十五 · 指标语义：TTFT、TPOT、吞吐、显存、功耗各自度量什么</h3>\n<p>五个指标度量的是不同资源，混在一张表里比较会得出错误结论。TTFT（首 token 时间）由预填阶段的矩阵乘与 KV cache 写入主导，受 prompt 长度与预填批大小支配；TPOT（每输出 token 时间）由解码阶段的权重带宽与 KV cache 读带宽主导，受并发批大小与 KV 长度支配；吞吐（tokens/s 或 requests/s）是二者的折中，取决于调度器如何把预填与解码交错；显存占用决定最大并发与最大上下文；功耗则约束持续吞吐与机架功率预算。SmoothQuant 的 W8A8 主要改善 TPOT 与显存，对 TTFT 的改善取决于预填阶段是否同样受权重带宽约束。</p>\n<p>机制上，解码阶段每步只处理一个 token，矩阵乘是访存受限的：权重从 HBM 读一遍、激活只读一行，时间近似正比于权重字节数除以带宽。权重位宽减半，TPOT 的权重项近似减半；但 KV cache 读与注意力计算不随权重量化变化，所以 TPOT 的改善有上限。设权重访存占比 $\\rho$，则 TPOT 改善上界为 $1/(\\rho/2 + (1-\\rho))$。工程上 $\\rho$ 随模型规模与 KV 长度变化：长上下文时 KV 读占主导，权重量化对 TPOT 的帮助被稀释。具体例子：7B 级模型短上下文解码时权重访存占大头，W8A8 收益明显；而同模型在数万 token 上下文下，KV cache 读成为瓶颈，此时应把优化预算转向 KV 量化与分页管理，而不是继续调 alpha。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>主导资源</th><th>受 SmoothQuant 影响的方式</th><th>不可比风险</th></tr></thead><tbody><tr><td>TTFT</td><td>预填矩阵乘、KV 写入</td><td>预填权重带宽下降；激活量化内核效率决定净收益</td><td>prompt 长度分布不同则不可比</td></tr><tr><td>TPOT</td><td>权重带宽、KV 读带宽</td><td>权重字节减半，改善受 KV 占比稀释</td><td>并发批大小与 KV 长度不同则不可比</td></tr><tr><td>吞吐</td><td>调度器、显存容量</td><td>显存下降允许更大批，间接提升吞吐</td><td>调度策略与 SLO 约束不同则不可比</td></tr><tr><td>显存</td><td>权重 + KV + 激活峰值</td><td>权重线性下降；激活峰值取决于量化粒度</td><td>上下文上限与并发设定不同则不可比</td></tr><tr><td>功耗</td><td>HBM 与张量核活动</td><td>带宽活动下降带来功耗下降</td><td>机架配置与时钟策略不同则不可比</td></tr></tbody></table>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-46\">四十六 · batch 与并发：为什么“同一加速比”在不同负载下不成立</h3>\n<p>量化收益对 batch 极度敏感。小 batch 解码是纯访存受限，权重位宽减半几乎线性转化为 TPOT 改善；大 batch 时矩阵乘转为计算受限，低精度张量核的吞吐上限成为约束，此时收益取决于内核能否在整数或低精度路径上跑满，而非带宽。并发数则通过 KV cache 显存占用间接影响：权重显存下降释放的空间可以换更多并发，但并发上升又推高 KV 读带宽，可能把瓶颈从权重搬到 KV。因此“W8A8 带来 N 倍吞吐”这类陈述必须绑定 batch 与并发区间，否则不可复现。</p>\n<p>伪代码思路：容量规划时先固定 SLO（如 TPOT 上限、TTFT 上限），再扫 batch 与并发，找出满足 SLO 的最大并发，比较量化前后的该值。这比比较峰值吞吐更有工程意义，因为峰值吞吐往往在违反 SLO 的配置下取得。</p>\n<div class=\"formula\">$$ C_{\\max} \\approx \\left\\lfloor \\frac{M_{\\text{HBM}} - M_{W} - M_{\\text{act}}}{M_{\\text{KV per seq}}} \\right\\rfloor,\\quad M_{W}\\propto P\\cdot b_w $$</div>\n<p>其中 $M_W$ 为权重显存，$M_{\\text{KV per seq}}$ 为单序列 KV 占用。权重位宽减半使 $M_W$ 减半，$C_{\\max}$ 上升，但上升幅度取决于 KV 项是否已成为分母主体。具体例子：权重显存从数十 GB 降到一半，若 KV 单序列占用不变，可容纳并发近似翻倍；但若上下文很长使 KV 项远大于权重项，翻倍效应消失。工程判断：报告吞吐时必须同时给出 batch、并发、上下文长度与 SLO 约束，四者缺一，数字不可比。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-47\">四十七 · 校准口径：分布、序列长度与阶段差异如何污染数字</h3>\n<p>校准集是量化精度的隐形变量，也是基准不可比的主要来源之一。SmoothQuant 只需前向统计逐通道激活极值与权重极值，解析求平滑系数，无反向传播；但极值估计对样本规模、序列长度与领域覆盖敏感。校准集短、领域窄，离群通道识别不准，缩放系数失准，量化后精度在真实负载上塌陷。更隐蔽的是阶段差异：分离式预填与解码部署中，预填阶段激活极值统计与解码阶段不同，若共用一套量化参数，解码阶段可能出现精度塌陷。因此基准必须声明校准集与推理负载是否同分布。</p>\n<p>机制上，平滑系数 $s_j$ 由激活与权重逐通道极值按 alpha 组合，alpha 取零退化为仅权重量化、取一退化为仅激活平滑。alpha 是部署调优的关键旋钮，但它是按层类型调的：注意力投影层与全连接层的极值分布不同，统一常数会让部分层权重量化误差上升。基准若只报一个全局 alpha 下的数字，读者无法判断该配置在其他层组合上是否成立。具体例子：文本校准集直接用于音频生成模型，声码器前馈层的激活分布与文本不匹配，量化后输出明显失真——这不是量化方法失效，而是校准口径错配，此类数字与文本任务的数字不可比。</p>\n<ul><li>校准样本规模决定极值估计稳定性，样本过少则离群通道漏检。</li><li>序列长度需覆盖目标部署的上下文分布，长序列放大激活极值波动。</li><li>领域覆盖决定离群通道是否被代表，跨域部署需分域校准或按层回退。</li><li>预填与解码阶段需分别校准，避免共用参数导致解码精度塌陷。</li></ul>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-48\">四十八 · 哪些提升不可比：五类常见误读</h3>\n<p>第一类，跨硬件档位比较加速比。同一 W8A8 配置在支持粗粒度激活量化内核的 GPU 上与在需重排的 GPU 上，端到端延迟差异来自内核效率而非量化方法，二者不可比。第二类，跨量化粒度比较。逐张量激活量化与按 token 分组量化的精度与内核开销都不同，只报其一而称“W8A8 精度恢复”会误导。第三类，跨校准集比较。校准分布偏移下的精度数字不能与同分布校准的数字并列。第四类，跨负载形态比较。短 prompt 高并发与长上下文低并发的 TTFT/TPOT 不可互换。第五类，把峰值吞吐当作可交付吞吐。违反 SLO 的峰值数字没有容量规划意义。</p>\n<p>工程上判断可比性的最低要求是：模型与层配置一致、硬件档位与内核路径一致、量化粒度与 alpha 配置一致、校准集与推理负载分布声明、batch/并发/上下文与 SLO 约束齐全。缺任一项，数字只能作为定性参考。具体例子：两份报告都称 W8A8 使 TPOT 改善，一份在短上下文小 batch 下测得，另一份在长上下文大并发下测得，前者反映权重带宽收益，后者反映 KV 瓶颈下的稀释效应，把两者平均或并列都是错误口径。</p>\n<div class=\"formula\">$$ \\text{可比性} = \\mathbb{1}[\\text{模型}] \\cdot \\mathbb{1}[\\text{硬件+内核}] \\cdot \\mathbb{1}[\\text{量化粒度+}\\alpha] \\cdot \\mathbb{1}[\\text{校准分布}] \\cdot \\mathbb{1}[\\text{负载+SLO}] $$</div>\n<p>该式不是数学定理，而是报告规范：任一因子为零，比较即无效。落地做法是基准表按因子分组，每组内只做同口径对比，跨组只做定性描述。对 Blackwell 部署，还需额外标注是否启用 2-SM MMA 与 TMEM 路径，因为低精度矩阵乘的累加布局直接决定激活量化粒度能否被内核吸收。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-49\">四十九 · 监控项与失败模式如何进入基准</h3>\n<p>基准不只测一次峰值，还要测稳定性。SmoothQuant 的失败模式是校准分布偏移使某层激活超出量化范围，表现为输出重复或截断；工程上需按层回退高精度并监控逐层极值漂移。因此基准应包含三类监控：逐层激活极值漂移、量化后输出与高精度输出的余弦相似度、端到端首包延迟。前两者是精度护栏，后者是 SLO 护栏。只报吞吐不报护栏，等于把精度塌陷风险留给线上。</p>\n<p>机制上，极值漂移监控可以在线采样少量请求，统计各层激活最大绝对值与校准值的比值；超过阈值即触发该层回退。回退的代价是显存与带宽回升，因此基准应报告“回退层比例”与对应的吞吐折损，而不是假设全层 W8A8 恒成立。具体例子：某层因长尾输入频繁触发回退，整网有效位宽介于 8 与 16 之间，此时报“W8A8 吞吐”就高估了实际收益。工程判断：把回退率纳入容量规划，按有效位宽而非标称位宽估算显存与带宽，才能得到可交付的吞吐与并发。</p>\n<p>最后落在具体机制上：基准的可信度取决于是否把量化参数、内核路径与回退策略当作一等公民记录。对 SmoothQuant，这意味着每条性能数字都应附带 alpha 配置、激活量化粒度、校准集分布、预填/解码是否分阶段校准、以及回退层比例；缺这些字段的倍数，在 Blackwell 部署评审中不应被采信。</p>\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-50\">五十 · 迁移到新模型：先判断“离群通道是否仍是主要矛盾”</h3>\n<p>SmoothQuant 的等价变换本身与模型结构无关，它只要求目标层是形如 <span class=\"inline\">Y = XW + b</span> 的线性映射，且激活在输入通道维度上存在可统计的极值结构。因此迁到新模型时，第一件要判断的不是“能不能套公式”，而是“这套模型的激活离群是否仍集中在少数通道、且这些通道是否与权重列一一对应”。Transformer 的注意力投影与 MLP 投影满足这一条件；卷积层在展平为隐式矩阵乘后也满足，但通道语义从“特征维”变成“输出通道 × 卷积核位置”的混合维度，逐通道极值统计不再对应单一语义，平滑系数的可解释性与可调性同时下降。</p>\n<p>更关键的边界在结构耦合上。若模型使用跨层共享权重、或权重在推理时动态生成（如某些混合专家路由后的即时拼装），则“权重列极值离线固化”的前提被破坏，平滑系数无法在部署前解析求解。此时可行的退化路径是只对激活做平滑、把 <span class=\"inline\">alpha</span> 推向 1，代价是权重量化误差不受控，需要逐层验证。判断准则可以写成一个粗略的筛查式：对每一层统计激活逐通道最大绝对值与中位数的比值 <span class=\"inline\">r_j</span>，若 <span class=\"inline\">max_j r_j</span> 远大于其余通道的分布上沿，平滑有收益；若所有通道比值接近，平滑只是把噪声在激活与权重之间来回搬，收益趋零。</p>\n<div class=\"formula\">$$ \\kappa = \\frac{\\max_j \\max(|X_{:,j}|)}{\\mathrm{median}_j \\max(|X_{:,j}|)} $$</div>\n<p><span class=\"inline\">kappa</span> 是离群强度的粗指标。工程代价上，逐层筛查需要一次完整校准前向，属于一次性离线开销；但若模型层数多、校准序列长，这次前向的显存峰值会接近推理峰值，需要在校准阶段就做好批大小与序列长度的折中。具体例子：把一套文本校准流程直接搬到带卷积前置层的多模态模型，卷积层的 <span class=\"inline\">kappa</span> 往往低于注意力层，强行套用同一 <span class=\"inline\">alpha</span> 会让卷积层权重量化误差上升而激活收益有限，正确做法是按层类型分组调 <span class=\"inline\">alpha</span>，而不是全局一个常数。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-51\">五十一 · 迁移到新领域：校准分布决定成败，音频是最典型的反例</h3>\n<p>跨领域迁移的核心代价不在算法，而在校准集。平滑系数由激活与权重的逐通道极值共同决定，极值估计对分布敏感；文本校准集统计出的离群通道，在音频、语音、代码、结构化表格输入上未必是同一批通道。对音频生成推理，声码器前馈层与注意力投影层可以套用同一变换，但音频激活的数值分布与文本不同——帧间连续性强、动态范围随音量与采样率变化，用文本校准集求出的缩放系数会让声码器输出出现明显失真。这不是精度小幅下降，而是可听的音质劣化，属于必须按领域重新校准的硬边界。</p>\n<p>迁移时的最小改动集可以归纳为三步：换校准数据、重估极值、重解 <span class=\"inline\">alpha</span>。校准样本规模与领域覆盖决定极值估计稳定性，样本太少会让离群通道识别随机化，样本领域太窄会让长尾输入在推理时溢出量化范围。工程上应把校准集按目标负载的输入长度分布分层采样，而不是均匀采样；长序列会放大激活极值波动，短序列则低估极值，两者混采才能让缩放系数在变长请求下不失准。</p>\n<p>代价层面，跨领域重校准的显存与带宽开销与一次推理前向同量级，但它是离线一次性的；真正的持续成本是监控。部署后需跟踪逐层激活极值漂移与量化后输出与高精度输出的余弦相似度，一旦某层极值漂移超出校准时的统计范围，就按层回退高精度。这个回退机制是跨领域迁移能否稳住的下限，而不是可选项。具体例子：同一套 W8A8 图在文本上稳定，迁到音频生成后若只换权重不换校准集，失败模式表现为输出重复或截断，定位手段就是逐层极值漂移监控。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-52\">五十二 · 迁移到分离式部署：预填与解码必须分阶段校准</h3>\n<p>分离式预填/解码（disaggregated prefill/decode）是这套方案迁移时最容易被忽略的边界。预填阶段处理长 prompt，激活极值由长序列的注意力与 MLP 输入决定；解码阶段逐 token 生成，激活极值分布更窄但批内 token 数随连续批处理波动。两个阶段的激活统计不同，若共用一套量化参数，解码阶段会出现精度塌陷——不是预填算错，而是解码时激活落在预填校准出的粗步长区间里，有效量化级不足。</p>\n<p>正确做法是按阶段分别校准，各自求平滑系数与量化参数，并在部署图上把两套参数绑定到各自的执行路径。代价是校准工作量翻倍、参数量翻倍，显存上多出一份缩放因子（相对权重与 KV cache 可忽略），但换来的是解码阶段不塌陷。调度侧还要注意：连续批处理让解码阶段的批组成动态变化，批内不同请求的激活极值叠加后可能超出单请求校准的范围，因此解码阶段的量化参数应按目标批大小上限校准，而不是按单请求校准。</p>\n<div class=\"formula\">$$ s_j^{(\\text{phase})} = \\frac{\\max(|X^{(\\text{phase})}_{:,j}|)^{\\alpha}}{\\max(|W_{j,:}|)^{1-\\alpha}},\\quad \\text{phase}\\in\\{\\text{prefill},\\text{decode}\\} $$</div>\n<p>并行与通信维度上，张量并行切分后每个卡只持有局部通道，缩放因子必须按切分后的局部通道重新统计，否则跨卡拼接时缩放不一致会引入系统性偏差。这是迁移到多卡部署时的必改项，而不是调优项。具体例子：一套单卡校准好的 W8A8 图直接按张量并行切到多卡，若沿用全局缩放因子，各卡反量化后的局部结果在归约时尺度不匹配，表现为输出整体偏移而非随机噪声，诊断上可通过逐卡输出与单卡高精度输出的比对定位。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-53\">五十三 · 规模上限：比特数、粒度与内核布局三者互相牵制</h3>\n<p>这套方案的规模上限不在模型参数量，而在“量化粒度与硬件矩阵乘内核布局的匹配度”。激活逐张量或按 token 分组量化可复用高吞吐矩阵乘内核；一旦为了救精度退到逐通道激活量化，就需要额外重排与缩放，访存开销上升，显存收益被抵消。因此规模上限的第一条约束是：当模型大到单层激活离群通道数随宽度增长而增多、逐张量量化无法覆盖时，只能靠更细的 token 分组，而分组越细，内核效率越低。这是一个单调的取舍曲线，不存在免费午餐。</p>\n<p>第二条约束是比特数。权重逐通道量化的缩放因子离线固化进权重布局，显存随比特数线性下降；但激活侧的有效比特数由离群通道决定，平滑只是把难度在激活与权重之间重新分配，不改变总难度。当 <span class=\"inline\">alpha</span> 过度偏向平滑激活时，权重量化误差上升，整网误差由权重侧主导；当 <span class=\"inline\">alpha</span> 偏向权重时，激活侧离群残留。规模越大、层类型越杂，单一 <span class=\"inline\">alpha</span> 越难覆盖，必须按层类型分组调优，调优成本随层类型数量线性增长，这是规模上限的第二条软约束。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>必改项</th><th>不适用/退化信号</th><th>主要代价</th></tr></thead><tbody><tr><td>新模型结构</td><td>逐层筛查离群强度、按层类型分组调 alpha</td><td>权重动态生成、跨层共享导致离线固化失效</td><td>校准前向显存峰值接近推理峰值</td></tr><tr><td>新领域（音频等）</td><td>换领域校准集、重估极值、重解 alpha</td><td>文本校准集直接套用导致声码器失真</td><td>离线重校准 + 持续极值漂移监控</td></tr><tr><td>分离式部署</td><td>预填/解码分阶段校准、按批大小上限校准解码</td><td>共用一套参数导致解码阶段塌陷</td><td>校准工作量与参数量翻倍</td></tr><tr><td>多卡并行</td><td>按切分后局部通道重统缩放因子</td><td>沿用全局因子导致归约尺度不匹配</td><td>逐卡校准与一致性校验</td></tr></tbody></table>\n<p>第三条约束来自失败模式的可观测性。校准分布偏移使某层激活超出量化范围时，表现为输出重复或截断，这类失败在长上下文与大批调度下更容易触发，而材料未给出长序列与批调度下的实测实时率，意味着规模上限的实时侧边界只能靠部署侧自测确定，不能靠方法本身保证。工程判断是：把逐层极值漂移监控与按层回退高精度作为规模扩张的前置条件，先能观测再谈放大。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-54\">五十四 · 不适用清单与工程判断</h3>\n<p>明确不适用或收益极低的情形有四类。其一，激活分布本身接近均匀、无明显离群通道的模型，平滑只是把量化噪声在激活与权重间搬运，<span class=\"inline\">kappa</span> 接近 1 时不应启用。其二，权重在推理时无法离线固化的结构，逐通道权重量化的前提被破坏。其三，对数值等价性要求极高的场景，等价变换在数学上不改变层输出，但低精度矩阵乘与反量化引入的舍入误差仍在，不能宣称比特级等价。其四，只关注权重量化而忽略激活量化粒度与内核布局匹配的部署，会在推理时引入额外重排开销抵消显存收益，这是迁移中最常见的负收益来源。</p>\n<p>工程判断可以收敛为一条决策链：先测 <span class=\"inline\">kappa</span> 判断离群是否为主要矛盾；再确认权重可离线固化；再按目标领域与部署形态（是否分离式、是否多卡）确定校准集与分阶段参数；最后按层类型分组调 <span class=\"inline\">alpha</span> 并建立逐层极值漂移监控与回退路径。每一步都有明确的失败信号与回退动作，而不是靠口号式的“端到端量化”。迁移的边界不在公式，而在校准分布、阶段划分与内核布局这三处；把这三处当成部署配置而非算法细节，这套方案才能在新模型与新领域上稳住。</p>\n\n<h3 id=\"paper-smoothquant-accurate-and-efficient-p-2022-sec-55\">五十五 · 迁移边界：平滑系数不是常数，量化粒度决定收益能否落地</h3>\n<p>把 SmoothQuant 搬到新模型时，最先失效的不是公式而是假设：<span class=\"formula-inline\">s<sub>j</sub></span> 由激活与权重的逐通道极值解析求出，这要求校准集覆盖真实推理的输入分布。文本模型的长上下文请求会放大激活极值波动，若校准序列长度短于部署上下文，离群通道识别就会偏移，缩放系数失准后表现为某层激活溢出量化范围、输出重复或截断。工程判断是：校准集必须按目标部署的上下文分布取样，并在上线后持续监控逐层激活极值漂移，对漂移超阈的层按层回退高精度，而不是整网回滚。音频生成是更硬的边界——声码器前馈层与注意力投影层可套用同一等价变换，但音频激活分布与文本不同，用文本校准集直接校准会让量化后声码器输出明显失真，必须用音频校准集重新求 <span class=\"formula-inline\">s</span>。</p>\n<p>平滑强度 <span class=\"formula-inline\">α</span> 是部署调优的关键旋钮，取零退化为仅权重量化、取一退化为仅激活平滑。把它当固定常数套到所有层是典型失效模式：过度平滑会把量化难度推给权重，权重量化误差上升；平滑不足则激活离群通道仍主导逐张量缩放因子。代价体现在精度而非速度上——权重逐通道量化离线固化，显存随比特数线性下降，但误差一旦落到权重侧就无法在推理时补救。因此按层类型（注意力投影、MLP、输出头）分别调 <span class=\"formula-inline\">α</span> 是必要的，缺少自适应选择机制意味着这是一次人工离线搜索，规模越大调优成本越高。</p>\n<p>规模上限主要来自量化粒度与内核布局的匹配。激活逐张量或按 token 分组可复用高吞吐矩阵乘内核；一旦为了精度退回逐通道激活量化，就需要额外重排与在线缩放，访存开销上升，可能抵消显存收益。用公式表达这个取舍：有效收益 ≈ 带宽节省 − 重排开销，前者随比特数下降线性增长，后者与激活张量规模成正比，长序列、大 batch 下重排占比更高。在分离式预填/解码部署中还有一层边界：预填阶段与解码阶段的激活极值统计不同，共用一套量化参数会让解码阶段精度塌陷，需按阶段分别校准。张量并行切分后，缩放因子要按切分后的局部通道重新统计，否则跨卡不一致；KV cache 应保持高精度或单独量化，避免与权重激活量化共用缩放因子导致误差叠加。</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>必须改动</th><th>不适用/失效条件</th></tr></thead><tbody><tr><td>长上下文文本</td><td>校准序列覆盖部署上下文，监控极值漂移</td><td>校准短于部署长度，离群通道识别偏移</td></tr><tr><td>音频生成</td><td>音频校准集重求 s，声码器逐层调 α</td><td>沿用文本校准，声码器输出失真</td></tr><tr><td>分离式预填/解码</td><td>两阶段分别校准量化参数</td><td>共用参数，解码阶段精度塌陷</td></tr><tr><td>张量并行</td><td>按局部通道重统计缩放因子</td><td>跨卡缩放不一致，累加误差叠加</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">SmoothQuant: Accurate and </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Efficient Pos…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2022 · arXiv preprint</text></svg><figcaption><b>家谱</b> · SmoothQuant: Accurate a… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出（材料未列出具体评测数据集）</td></tr><tr><td>基线</td><td>未给出（材料未列出对比基线）</td></tr><tr><td>主要结果</td><td>材料未给出具体精度与吞吐数字；可核验的机制性结论是：逐张量激活量化在存在离…</td></tr><tr><td>消融</td><td>材料未给出消融表；可推断的消融维度为平滑强度取值、激活量化粒度（逐张量对比…</td></tr><tr><td>局限</td><td>平滑强度参数需按模型与层类型调；过度平滑会把量化难度推给权重，导致权重量化…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-smoothquant-accurate-and-efficient-p-2022 · 共 9 个片段</p>\n";break;}}})();
